// and a persistent "What's New" tab. `serviceTypes` scopes visibility: a user
// only sees announcements for services they actually have.
// ---------------------------------------------------------------------------
model UpdateAnnouncement {
  id            String                 @id @default(cuid())
  title         String
  body          String // Markdown
  // What KIND of change this is, author-set (never inferred from the title) —
  // drives the icon/tone and the What's New page's category filter.
  // FEATURE | IMPROVEMENT | BUGFIX. Defaults to FEATURE for old rows written
  // before this column existed, since every one of them announced something
  // new rather than a fix.
  kind          String                 @default("FEATURE")
  serviceTypes  String[] // e.g. ["GAME","VPS","HOSTING"] — empty = all services
  gameFamilies  String[] // e.g. ["minecraft","rust"] — which games this update covers (GAME-scoped only; empty = not game-specific)
  screenshotUrl String? // relative path to an uploaded screenshot
  status        String                 @default("DRAFT") // DRAFT | PUBLISHED
  publishedAt   DateTime?
  createdAt     DateTime               @default(now())
  updatedAt     DateTime               @updatedAt
  seenBy        UserAnnouncementSeen[]

  @@index([status, publishedAt])
}

model UserAnnouncementSeen {
  id             String             @id @default(cuid())
  userId         String
  user           User               @relation(fields: [userId], references: [id], onDelete: Cascade)
  announcementId String
  announcement   UpdateAnnouncement @relation(fields: [announcementId], references: [id], onDelete: Cascade)
  seenAt         DateTime           @default(now())

  @@unique([userId, announcementId])
  @@index([userId])
}

// ---------------------------------------------------------------------------
// Reddit marketing templates — internal admin library of copy-paste-ready
// post title/body pairs organized by category (e.g. "Game Servers", "VPS") and
// optional subcategory (e.g. one per game under "Game Servers"). Subreddits
// attach at whichever level makes sense; templates carry a perspective tag so
// the owner can pick an authentic-sounding angle before posting.
// ---------------------------------------------------------------------------
model RedditCategory {
  id            String              @id @default(cuid())
  name          String
  slug          String              @unique
  position      Int                 @default(0)
  createdAt     DateTime            @default(now())
  subcategories RedditSubcategory[]
  subreddits    RedditSubreddit[]
  templates     RedditTemplate[]
}

model RedditSubcategory {
"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { requireArea } from "./rbac";
import { GAME_FAMILIES, type GameFamily } from "./games";

/**
 * Update Announcements — service-specific release notes pushed to customers.
 *
 * Admin creates a DRAFT, then explicitly publishes it (the approval gate).
 * Customers see a popup on first login after publish and a persistent
 * "What's New" feed. `serviceTypes` scopes visibility: a user only sees
 * announcements for services they actually have; empty = everyone.
 *
 * Admin actions are area-gated ("platform"). Customer actions self-auth via
 * `requireUser()` and only ever touch that user's own rows.
 */

/** Widened from the original 4 to match the concept's filter row and every
 *  real product area — DOMAINS/BILLING/PLATFORM were previously unrepresentable
 *  (an admin authoring a domains or platform-wide update had nowhere to put it
 *  but the general "empty = everyone" bucket). */
const SERVICE_TYPES = ["GAME", "VPS", "HOSTING", "DOMAINS", "MAIL", "BILLING", "PLATFORM"] as const;
export type ServiceType = (typeof SERVICE_TYPES)[number];

/** What kind of change an update is — author-set, drives the What's New
 *  page's icon/tone/filter. Never inferred from the title. */
const KINDS = ["FEATURE", "IMPROVEMENT", "BUGFIX"] as const;
export type AnnouncementKind = (typeof KINDS)[number];

// ---------- Admin ----------

export async function listAnnouncements() {
  await requireArea("platform");
  return db.updateAnnouncement.findMany({
    orderBy: { createdAt: "desc" },
    take: 200,
    include: { _count: { select: { seenBy: true } } },
  });
}

export async function createAnnouncement(input: {
  title: string;
  body: string;
  kind?: string;
  serviceTypes: string[];
  gameFamilies?: string[];
  screenshotUrl?: string | null;
}): Promise<{ error?: string; ok?: boolean }> {
  await requireArea("platform");
  const title = String(input.title ?? "").trim();
  if (!title) return { error: "Enter a title." };
  const body = String(input.body ?? "").trim();
  if (!body) return { error: "Enter a body." };

  const kind = (KINDS as readonly string[]).includes(input.kind ?? "") ? (input.kind as AnnouncementKind) : "FEATURE";

  // Validate service types — only allow known values.
  const serviceTypes = (input.serviceTypes ?? []).filter((t) =>
    (SERVICE_TYPES as readonly string[]).includes(t),
  );

  // Game families only make sense when the update is GAME-scoped. Validate
  // against the real game family list so a typo can never silently no-op.
  const gameFamilies = serviceTypes.includes("GAME")
    ? (input.gameFamilies ?? []).filter((g) => (GAME_FAMILIES as readonly string[]).includes(g))
    : [];

  // Screenshot must be a relative path, not an external URL.
  let screenshotUrl: string | null = null;
  if (input.screenshotUrl) {
    const u = input.screenshotUrl.trim();
    if (u && !u.startsWith("/")) return { error: "Screenshot must be a relative path (e.g. /uploads/announcements/img.png)." };
    screenshotUrl = u || null;
  }

  await db.updateAnnouncement.create({
    data: {
      title: title.slice(0, 200),
      body: body.slice(0, 10_000),
      kind,
      serviceTypes,
      gameFamilies,
      screenshotUrl,
      status: "DRAFT",
    },
  });
  revalidatePath("/admin/announcements");
  return { ok: true };
}

export async function publishAnnouncement(id: string): Promise<void> {
  await requireArea("platform");
  await db.updateAnnouncement.update({
    where: { id },
    data: { status: "PUBLISHED", publishedAt: new Date() },
  });
  revalidatePath("/admin/announcements");
}

export async function unpublishAnnouncement(id: string): Promise<void> {
  await requireArea("platform");
  await db.updateAnnouncement.update({
    where: { id },
    data: { status: "DRAFT" },
  });
  revalidatePath("/admin/announcements");
}

export async function deleteAnnouncement(id: string): Promise<void> {
  await requireArea("platform");
  await db.updateAnnouncement.delete({ where: { id } }).catch(() => undefined);
  revalidatePath("/admin/announcements");
}

// ---------- Customer ----------

/** Determine which service types the current user has active services for.
 *  BILLING and PLATFORM are unconditional — every account has a wallet, and a
 *  platform-wide change (a new region, an infra migration) affects everyone
 *  regardless of which products they've bought. */
async function getUserServiceTypes(userId: string): Promise<string[]> {
  const [servers, hosting, domain] = await Promise.all([
    db.server.findFirst({ where: { userId } }),
    db.hostingAccount.findFirst({ where: { userId } }),
    db.domain.findFirst({ where: { userId } }),
  ]);
  const types: string[] = ["BILLING", "PLATFORM"];
  if (servers) {
    const hasGame = await db.server.findFirst({
      where: { userId, gamePlanId: { not: null } },
    });
    if (hasGame) types.push("GAME");
    const hasVps = await db.server.findFirst({
      where: { userId, gamePlanId: null },
    });
    if (hasVps) types.push("VPS");
  }
  if (hosting) types.push("HOSTING");
  // MAIL: anyone with a hosting account potentially has mail; we keep it
  // simple and include MAIL for hosting customers too.
  if (hosting) types.push("MAIL");
  if (domain) types.push("DOMAINS");
  return types;
}

/**
 * PUBLISHED announcements the current user hasn't seen, filtered by service
 * types matching their actual services. An announcement with empty
 * serviceTypes[] is shown to everyone.
 */
export async function getUnseenAnnouncements() {
  const user = await requireUser();
  const userServices = await getUserServiceTypes(user.id);

  const announcements = await db.updateAnnouncement.findMany({
    where: {
      status: "PUBLISHED",
      seenBy: { none: { userId: user.id } },
    },
    orderBy: { publishedAt: "desc" },
  });

  // Filter by service type: show if announcement has no serviceTypes (global)
  // or if at least one of the user's service types matches.
  return announcements.filter(
    (a) =>
      a.serviceTypes.length === 0 ||
      a.serviceTypes.some((t) => userServices.includes(t)),
  );
}

/** Mark an announcement as seen by the current user. Upserts to stay idempotent. */
export async function markAnnouncementSeen(announcementId: string): Promise<void> {
  const user = await requireUser();
  await db.userAnnouncementSeen.upsert({
    where: {
      userId_announcementId: { userId: user.id, announcementId },
    },
    create: { userId: user.id, announcementId },
    update: {},
  });
}

export type WhatsNewEntry = {
  id: string;
  title: string;
  body: string;
  kind: AnnouncementKind;
  serviceTypes: string[];
  gameFamilies: string[];
  screenshotUrl: string | null;
  publishedAt: string; // ISO string for serialization
  seen: boolean;
};

/**
 * All PUBLISHED announcements, optionally filtered by service type, ordered
 * by publishedAt desc, with a `seen` boolean flag for the current user.
 */
export async function getWhatsNew(
  serviceFilter?: string,
): Promise<WhatsNewEntry[]> {
  const user = await requireUser();

  const where: Record<string, unknown> = { status: "PUBLISHED" };
  if (serviceFilter && (SERVICE_TYPES as readonly string[]).includes(serviceFilter)) {
    where.serviceTypes = { has: serviceFilter };
  }

  const announcements = await db.updateAnnouncement.findMany({
    where,
    orderBy: { publishedAt: "desc" },
    include: {
      seenBy: {
        where: { userId: user.id },
        take: 1,
      },
    },
  });

  return announcements.map((a) => ({
    id: a.id,
    title: a.title,
    body: a.body,
    kind: ((KINDS as readonly string[]).includes(a.kind) ? a.kind : "FEATURE") as AnnouncementKind,
    serviceTypes: a.serviceTypes,
    gameFamilies: a.gameFamilies,
    screenshotUrl: a.screenshotUrl,
    publishedAt: (a.publishedAt ?? a.createdAt).toISOString(),
    seen: a.seenBy.length > 0,
  }));
}

/**
 * Real counts behind the What's New page's stats card — every number here is
 * a straight aggregate over PUBLISHED rows, never estimated. "Major releases"
 * and "Fixes & improvements" are just `kind` grouped two ways, not a second
 * concept: a FEATURE is the "major" half, IMPROVEMENT + BUGFIX are the other.
 */
export async function getWhatsNewStats(): Promise<{
  total: number; newThisMonth: number; majorReleases: number; fixesAndImprovements: number;
}> {
  const monthStart = new Date();
  monthStart.setDate(1);
  monthStart.setHours(0, 0, 0, 0);
  const base = { status: "PUBLISHED" } as const;
  const [total, newThisMonth, majorReleases, fixesAndImprovements] = await Promise.all([
    db.updateAnnouncement.count({ where: base }),
    db.updateAnnouncement.count({ where: { ...base, publishedAt: { gte: monthStart } } }),
    db.updateAnnouncement.count({ where: { ...base, kind: "FEATURE" } }),
    db.updateAnnouncement.count({ where: { ...base, kind: { in: ["IMPROVEMENT", "BUGFIX"] } } }),
  ]);
  return { total, newThisMonth, majorReleases, fixesAndImprovements };
}
/* Shared display metadata for the What's New page — kept separate from
 * lib/actions-announcements.ts (a "use server" module can only export async
 * functions, so plain lookup tables live here instead).
 *
 * Per-entry icons are the REAL service icons already used in the deploy
 * wizard (components/nx/OrderBits.tsx's `SvcIcon`, `/nx/svc/<name>.webp`) —
 * not a new icon set invented for this page. Only GAME/VPS/HOSTING/DOMAINS/
 * MAIL have real art there; BILLING and PLATFORM fall back to a sprite-sheet
 * `Icon` mark since no SvcIcon asset exists for either.
 */
export type ServiceIconRef = { kind: "svc"; name: string } | { kind: "sprite"; name: string };

export const SERVICE_META: Record<string, { label: string; icon: ServiceIconRef }> = {
  GAME: { label: "Game servers", icon: { kind: "svc", name: "game" } },
  VPS: { label: "VPS", icon: { kind: "svc", name: "vps" } },
  HOSTING: { label: "Hosting", icon: { kind: "svc", name: "hosting" } },
  DOMAINS: { label: "Domains", icon: { kind: "svc", name: "domains" } },
  MAIL: { label: "Mail", icon: { kind: "svc", name: "email" } },
  BILLING: { label: "Billing", icon: { kind: "sprite", name: "card" } },
  PLATFORM: { label: "Platform", icon: { kind: "sprite", name: "sparkles" } },
};

export const SERVICE_ORDER = ["GAME", "VPS", "HOSTING", "DOMAINS", "MAIL", "BILLING", "PLATFORM"] as const;

/** Kind badges are text-only, not icon-led — the icon slot on every card is
 *  the service's, per the owner's own instruction; kind only needs a small
 *  tone-coded label ("New feature" / "Improvement" / "Bug fix"). */
export const KIND_META: Record<string, { label: string; badgeClass: string }> = {
  FEATURE: { label: "New feature", badgeClass: "badge" },
  IMPROVEMENT: { label: "Improvement", badgeClass: "badge badge-cyan" },
  BUGFIX: { label: "Bug fix", badgeClass: "badge badge-amber" },
};
import { requireUser } from "@/lib/auth";
import { getWhatsNew, getWhatsNewStats } from "@/lib/actions-announcements";
import { normalizePrefs } from "@/lib/prefs";
import { WhatsNewView } from "@/components/nx/WhatsNewView";

export const dynamic = "force-dynamic";

/* Real data throughout: entries + stats straight off `UpdateAnnouncement`
 * (getWhatsNew/getWhatsNewStats, lib/actions-announcements.ts), and the
 * "Stay in the loop" card's own state read off the SAME `notificationPrefs`
 * column Settings displays — never a fabricated "you're subscribed". */
export default async function WhatsNewPage() {
  const user = await requireUser();
  const [entries, stats] = await Promise.all([getWhatsNew(), getWhatsNewStats()]);
  const notifyOn = normalizePrefs(user.notificationPrefs).product;
  return <WhatsNewView entries={entries} stats={stats} notifyOn={notifyOn} />;
}
import { requireArea } from "@/lib/rbac";
import { PageHeader } from "@/components/ui/primitives";
import { listAnnouncements } from "@/lib/actions-announcements";
import { AnnouncementsAdmin } from "@/components/admin/AnnouncementsAdmin";

export const dynamic = "force-dynamic";

export default async function AdminAnnouncementsPage() {
  await requireArea("platform");
  const rows = await listAnnouncements();
  return (
    <div className="space-y-6">
      <PageHeader
        title="Update Announcements"
        sub="Write release notes and service updates. Drafts are private; published announcements appear to customers as a popup and in their What's New feed."
      />
      <AnnouncementsAdmin
        rows={rows.map((r) => ({
          id: r.id,
          title: r.title,
          body: r.body,
          kind: r.kind,
          serviceTypes: r.serviceTypes,
          gameFamilies: r.gameFamilies,
          screenshotUrl: r.screenshotUrl,
          status: r.status,
          publishedAt: r.publishedAt ? r.publishedAt.toISOString() : null,
          createdAt: r.createdAt.toISOString(),
          seenCount: r._count.seenBy,
        }))}
      />
    </div>
  );
}

"use client";

import { useEffect, useState, useTransition, useCallback } from "react";
import { createPortal } from "react-dom";
import {
  getUnseenAnnouncements,
  markAnnouncementSeen,
} from "@/lib/actions-announcements";
import { renderMarkdown } from "@/lib/blog";
import { GameCoverTile } from "@/components/customer/GameCoverTile";
import { GAME_DISPLAY, type GameFamily } from "@/lib/games";

type Announcement = {
  id: string;
  title: string;
  body: string;
  screenshotUrl: string | null;
  serviceTypes: string[];
  gameFamilies: string[];
  publishedAt: Date | null;
};

/**
 * Shows unseen update announcements as a modal popup, one at a time.
 * Mounted inside the dashboard layout so it only fires for authenticated users.
 * Uses createPortal to escape any transformed ancestors (same fix as
 * HeardAboutUsPrompt.tsx).
 */
export function AnnouncementPopup() {
  const [queue, setQueue] = useState<Announcement[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [, startTransition] = useTransition();

  useEffect(() => {
    let cancelled = false;
    getUnseenAnnouncements()
      .then((items) => {
        if (!cancelled) {
          setQueue(items);
          setLoaded(true);
        }
      })
      .catch(() => {
        // Soft-fail: never block the portal over a failed announcement fetch.
        if (!cancelled) setLoaded(true);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const dismiss = useCallback(() => {
    const current = queue[0];
    if (!current) return;
    // Remove from queue optimistically.
    setQueue((prev) => prev.slice(1));
    // Persist the seen record in the background.
    startTransition(async () => {
      try {
        await markAnnouncementSeen(current.id);
      } catch {
        /* best-effort */
      }
    });
  }, [queue]);

  // Nothing to show (not loaded, or no unseen announcements).
  if (!loaded || queue.length === 0) return null;
  if (typeof document === "undefined") return null;

  const current = queue[0];

  return createPortal(
    <div
      className="fixed inset-0 z-[70] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"
      role="dialog"
      aria-modal="true"
      aria-labelledby="announcement-title"
      onClick={dismiss}
    >
      <div
        className="card w-full max-w-2xl overflow-hidden motion-safe:animate-panel-in"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="border-b border-white/[0.06] bg-gradient-to-r from-brand-500/10 to-accent-blue/10 px-6 py-4">
          <div className="flex items-center gap-2">
            <span className="flex h-6 w-6 items-center justify-center rounded-full bg-brand-500/20 text-brand-300">
              <svg
                width="14"
                height="14"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="M11 3l1.8 4.9L17.7 9.7l-4.9 1.8L11 16.4l-1.8-4.9L4.3 9.7l4.9-1.8zM18 14.5l.85 2.15L21 17.5l-2.15.85L18 20.5l-.85-2.15L15 17.5l2.15-.85z" />
              </svg>
            </span>
            <span className="text-xs font-medium uppercase tracking-wider text-brand-300">
              What&apos;s new
            </span>
          </div>
          <h2
            id="announcement-title"
            className="mt-2 text-lg font-bold tracking-tight text-white"
          >
            {current.title}
          </h2>
          {current.serviceTypes.length > 0 && (
            <div className="mt-1.5 flex gap-1.5">
              {current.serviceTypes.map((t) => (
                <span
                  key={t}
                  className="rounded border border-white/10 bg-white/[0.05] px-1.5 py-0.5 text-[10px] text-slate-400"
                >
                  {t}
                </span>
              ))}
            </div>
          )}
        </div>

        {/* Body */}
        <div className="max-h-[60dvh] overflow-y-auto px-6 py-5">
          {current.gameFamilies.length > 0 && (
            <div className="mb-4">
              <p className="mb-2 text-[11px] font-medium uppercase tracking-wide text-slate-500">
                {current.gameFamilies.length > 1 ? "Games covered in this update" : "Game"}
              </p>
              <div className={`grid gap-2 ${current.gameFamilies.length === 1 ? "grid-cols-3" : "grid-cols-4 sm:grid-cols-5"}`}>
                {current.gameFamilies.map((g) => (
                  <div key={g} className="overflow-hidden rounded-lg border border-white/10">
                    <GameCoverTile family={g} name={GAME_DISPLAY[g as GameFamily]?.name ?? g} />
                    <p className="truncate bg-black/40 px-1.5 py-1 text-center text-[10px] font-medium text-slate-200">
                      {GAME_DISPLAY[g as GameFamily]?.name ?? g}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}
          <div
            dangerouslySetInnerHTML={{ __html: renderMarkdown(current.body) }}
          />
          {current.screenshotUrl && (
            <div className="mt-4">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={current.screenshotUrl}
                alt={`Screenshot for ${current.title}`}
                className="w-full rounded-xl border border-white/10 shadow-lg shadow-black/20"
                loading="lazy"
              />
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between border-t border-white/[0.06] px-6 py-4">
          <span className="text-xs text-slate-500">
            {queue.length > 1
              ? `1 of ${queue.length} updates`
              : ""}
          </span>
          <button className="btn-primary" onClick={dismiss}>
            {queue.length > 1 ? "Next" : "Got it"}
          </button>
        </div>
      </div>
    </div>,
    document.body,
  );
}
"use client";

import { useEffect, useRef } from "react";
import { isLightTheme, auroraComposite, auroraStrandGradient } from "./auroraTheme";

/* What's New's own light field — magenta/violet-led, matching the concept's
 * magenta "WHAT'S NEW" eyebrow and violet headline gradient, with a single
 * thin blue filament for contrast rather than a cyan-forward mix. Same
 * technique as Billing/Activity's aurora (canvas sine-path strokes, additive
 * blend, blurred halo + hard core) with its own ribbon family — steeper,
 * faster strands than Activity's calmer pair, and its own hue range.
 */
type Ribbon = {
  y: number; amp: number; freq: number; speed: number; phase: number;
  width: number; hue: [number, number]; alpha: number;
};

const RIBBONS: Ribbon[] = [
  { y: 0.16, amp: 0.20, freq: 0.8, speed: 0.18, phase: 0.6, width: 60, hue: [268, 312], alpha: 0.19 },
  { y: 0.32, amp: 0.14, freq: 1.2, speed: -0.15, phase: 3.4, width: 46, hue: [286, 326], alpha: 0.18 },
  { y: 0.22, amp: 0.09, freq: 1.8, speed: 0.24, phase: 5.1, width: 26, hue: [214, 246], alpha: 0.17 },
  { y: 0.28, amp: 0.05, freq: 2.9, speed: 0.33, phase: 2.0, width: 12, hue: [292, 320], alpha: 0.23 },
];

export function WhatsNewAurora() {
  const ref = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const cv = ref.current;
    if (!cv) return;
    const ctx = cv.getContext("2d", { alpha: true });
    if (!ctx) return;

    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    let raf = 0, t = 0, running = true;

    const fit = () => {
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      const r = cv.getBoundingClientRect();
      cv.width = Math.max(1, Math.round(r.width * dpr));
      cv.height = Math.max(1, Math.round(r.height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    const strand = (r: Ribbon, w: number, h: number, time: number, isLight: boolean) => {
      ctx.strokeStyle = auroraStrandGradient(ctx, r, w, isLight);
      ctx.lineWidth = r.width;
      ctx.lineCap = "round";
      ctx.beginPath();
      for (let x = 0; x <= w; x += 8) {
        const u = x / w;
        const y = h * (r.y
          + r.amp * Math.sin(u * Math.PI * 2 * r.freq + time * r.speed + r.phase)
          + r.amp * 0.4 * Math.sin(u * Math.PI * 2 * (r.freq * 1.7) - time * r.speed * 0.6));
        x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.stroke();
    };

    const draw = () => {
      if (!running) return;
      const w = cv.clientWidth, h = cv.clientHeight;
      const isLight = isLightTheme();
      ctx.clearRect(0, 0, w, h);
      ctx.globalCompositeOperation = auroraComposite(isLight);
      ctx.filter = "blur(30px)";
      for (const r of RIBBONS) strand(r, w, h, t, isLight);
      ctx.filter = "blur(4px)";
      for (const r of RIBBONS) strand({ ...r, width: r.width * 0.22, alpha: r.alpha * 1.5 }, w, h, t, isLight);
      ctx.filter = "none";
      for (const r of RIBBONS) strand({ ...r, width: Math.max(1.2, r.width * 0.045), alpha: Math.min(1, r.alpha * 1.9) }, w, h, t, isLight);
      ctx.globalCompositeOperation = "source-over";
      t += 0.016;
      raf = requestAnimationFrame(draw);
    };

    fit();
    if (reduced) {
      t = 2.4;
      const w = cv.clientWidth, h = cv.clientHeight;
      const isLight = isLightTheme();
      ctx.globalCompositeOperation = auroraComposite(isLight);
      ctx.filter = "blur(30px)";
      for (const r of RIBBONS) strand(r, w, h, t, isLight);
      ctx.filter = "none";
      for (const r of RIBBONS) strand({ ...r, width: Math.max(1.2, r.width * 0.045), alpha: Math.min(1, r.alpha * 1.9) }, w, h, t, isLight);
    } else {
      raf = requestAnimationFrame(draw);
    }

    const onResize = () => fit();
    const onVis = () => {
      if (document.hidden) { running = false; cancelAnimationFrame(raf); }
      else if (!reduced && !running) { running = true; raf = requestAnimationFrame(draw); }
    };
    window.addEventListener("resize", onResize);
    document.addEventListener("visibilitychange", onVis);
    return () => {
      running = false;
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", onResize);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, []);

  return (
    <div aria-hidden
         className="pointer-events-none fixed inset-x-0 top-0 z-0 h-[460px] overflow-hidden lg:left-[76px] xl:left-[248px]">
