              {!entry.seen && <span className="badge badge-mint text-[10px]">New</span>}
              <span className={kindMeta.badgeClass + " text-[10px]"}>{kindMeta.label}</span>
              {entry.serviceTypes.length > 0 && (
                <div className="ml-auto flex flex-wrap gap-1.5">
                  {entry.serviceTypes.map((t) => <ServiceTag key={t} type={t} />)}
                </div>
              )}
            </div>

            <h3 className="mt-1.5 text-[15.5px] font-extrabold text-white">{entry.title}</h3>

            {entry.gameFamilies.length > 0 && (
              <div className="mt-3">
                {entry.gameFamilies.length > 1 && (
                  <p className="mb-2 text-[10.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">
                    Games covered in this update
