export function AnnouncementsAdmin({ rows }: { rows: Row[] }) {
  const router = useRouter();
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [kind, setKind] = useState("FEATURE");
  const [serviceTypes, setServiceTypes] = useState<string[]>([]);
  const [gameFamilies, setGameFamilies] = useState<string[]>([]);
  const [screenshotUrl, setScreenshotUrl] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [previewRow, setPreviewRow] = useState<PreviewData | null>(null);
  function toggleService(val: string) {
    setServiceTypes((prev) =>
      prev.includes(val) ? prev.filter((v) => v !== val) : [...prev, val],
    );
    if (val === "GAME") setGameFamilies([]);
  }
  function toggleGame(val: string) {
    setGameFamilies((prev) =>
      prev.includes(val) ? prev.filter((v) => v !== val) : [...prev, val],
    );
  }
  async function submit() {
    setErr("");
    setBusy(true);
    const res = await createAnnouncement({
      title,
      body,
      kind,
      serviceTypes,
      gameFamilies,
      screenshotUrl: screenshotUrl || null,
    });
    setBusy(false);
    if (res.error) {
      setErr(res.error);
      return;
    }
    setTitle("");
    setBody("");
    setKind("FEATURE");
    setServiceTypes([]);
    setGameFamilies([]);
    setScreenshotUrl("");
    router.refresh();
  }
  async function doPublish(id: string) {
    await publishAnnouncement(id);
    router.refresh();
  }
  async function doUnpublish(id: string) {
    await unpublishAnnouncement(id);
    router.refresh();
  }
  async function doDelete(id: string) {
    if (!confirm("Delete this announcement permanently?")) return;
    await deleteAnnouncement(id);
    router.refresh();
  }
  return (
    <div className="space-y-6">
      {/* Create form */}
      <div className="card space-y-4">
        <p className="text-sm font-semibold text-white">New announcement</p>
        <input
          className="input"
          placeholder="Title (e.g. New backup system, Game server mods)"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          maxLength={200}
        />
        <MarkdownField
          value={body}
          onChange={setBody}
          placeholder="Write the update — use the toolbar above for bold, headings, lists, links and images."
        />
        <div className="flex flex-wrap items-center gap-4">
          <span className="text-xs font-medium text-slate-400">Kind:</span>
          {KIND_OPTIONS.map((opt) => (
            <label key={opt.value} className="flex items-center gap-1.5 text-sm text-slate-300">
              <input
                type="radio"
                name="kind"
                checked={kind === opt.value}
                onChange={() => setKind(opt.value)}
                className="accent-brand-500"
              />
              {opt.label}
            </label>
          ))}
        </div>
        <div className="flex flex-wrap items-center gap-4">
          <span className="text-xs font-medium text-slate-400">
            Service types (empty = shown to all):
          </span>
          {SERVICE_OPTIONS.map((opt) => (
            <label
              key={opt.value}
              className="flex items-center gap-1.5 text-sm text-slate-300"
            >
              <input
                type="checkbox"
                checked={serviceTypes.includes(opt.value)}
                onChange={() => toggleService(opt.value)}
                className="accent-brand-500"
              />
              {opt.label}
            </label>
          ))}
        </div>
        {serviceTypes.includes("GAME") && (
          <div className="rounded-xl border border-white/[0.06] bg-black/20 p-3">
            <p className="mb-2 text-xs font-medium text-slate-400">
              Games this update covers (optional — leave empty for a general game-server update). Pick multiple for a batch update; each gets its own cover in the customer feed.
            </p>
            <div className="grid grid-cols-4 gap-2 sm:grid-cols-6 md:grid-cols-8">
              {GAME_FAMILIES.map((family) => {
                const selected = gameFamilies.includes(family);
                return (
                  <button
                    key={family}
                    type="button"
                    onClick={() => toggleGame(family)}
                    className={`group relative overflow-hidden rounded-lg border transition-colors ${
                      selected ? "border-brand-400/70" : "border-white/[0.08] hover:border-white/20"
                    }`}
                  >
                    <GameCoverTile family={family} name={GAME_DISPLAY[family].name} />
                    <span className="absolute inset-x-0 bottom-0 truncate bg-black/60 px-1 py-0.5 text-[9px] font-medium text-white">
                      {GAME_DISPLAY[family].name}
                    </span>
                    {selected && (
                      <span className="absolute right-1 top-1 flex h-4 w-4 items-center justify-center rounded-full bg-brand-500 text-[9px] text-white">
                        ✓
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        )}
        <input
          className="input text-sm"
          placeholder="Screenshot path (optional, e.g. /uploads/announcements/screenshot.png)"
          value={screenshotUrl}
          onChange={(e) => setScreenshotUrl(e.target.value)}
        />
        <div className="flex items-center gap-3">
          <button
            className="btn-primary"
            onClick={submit}
            disabled={busy || !title.trim() || !body.trim()}
          >
            {busy ? "Creating..." : "Create draft"}
          </button>
          <button
            type="button"
            className="text-xs text-slate-400 hover:text-white"
            disabled={!title.trim() && !body.trim()}
            onClick={() =>
              setPreviewRow({
                title: title || "Untitled",
                body,
                kind,
                serviceTypes,
                gameFamilies,
                screenshotUrl: screenshotUrl || null,
              })
            }
          >
            Preview
          </button>
        </div>
        {err && <p className="text-sm text-red-400">{err}</p>}
      </div>
      {/* Announcements list */}
      <div className="card p-0">
        <div className="border-b border-white/[0.06] px-4 py-3 text-sm font-semibold text-white">
          All announcements ({rows.length})
        </div>
        {rows.length === 0 ? (
          <p className="px-4 py-6 text-sm text-slate-400">
            No announcements yet — use the form above to create your first one.
          </p>
        ) : (
          <ul className="divide-y divide-white/[0.06]">
            {rows.map((r) => (
              <li
                key={r.id}
                className="flex items-start justify-between gap-3 px-4 py-4"
              >
                <div className="min-w-0 flex-1">
                  <p className="flex items-center gap-2 text-sm font-medium text-slate-100">
                    <span
                      className={`h-2 w-2 shrink-0 rounded-full ${STATUS_DOT[r.status] ?? STATUS_DOT.DRAFT}`}
                    />
                    <span className="truncate">{r.title}</span>
                    <span
                      className={`inline-flex shrink-0 items-center rounded-full border px-2 py-0.5 text-[10px] font-medium ${STATUS_BADGE[r.status] ?? STATUS_BADGE.DRAFT}`}
                    >
                      {r.status.toLowerCase()}
                    </span>
                  </p>
                  {r.serviceTypes.length > 0 && (
                    <p className="mt-1 flex gap-1.5">
                      {r.serviceTypes.map((t) => (
                        <span
                          key={t}
                          className="rounded border border-white/10 bg-white/[0.05] px-1.5 py-0.5 text-[10px] text-slate-400"
                        >
                          {t}
                        </span>
                      ))}
                    </p>
                  )}
                  {r.gameFamilies.length > 0 && (
                    <div className="mt-1.5 flex flex-wrap gap-1.5">
                      {r.gameFamilies.map((g) => (
                        <span
                          key={g}
                          className="flex items-center gap-1 rounded-full border border-white/10 bg-white/[0.05] py-0.5 pl-0.5 pr-2 text-[10px] text-slate-300"
                        >
                          <span className="h-4 w-4 overflow-hidden rounded-full">
                            <GameCoverTile family={g} name={GAME_DISPLAY[g as keyof typeof GAME_DISPLAY]?.name ?? g} />
                          </span>
                          {GAME_DISPLAY[g as keyof typeof GAME_DISPLAY]?.name ?? g}
                        </span>
                      ))}
                    </div>
                  )}
                  <p className="mt-1 line-clamp-2 text-xs text-slate-500">
                    {r.body}
                  </p>
                  <p className="mt-1 text-[11px] text-slate-500">
                    Created {new Date(r.createdAt).toLocaleDateString()}
                    {r.publishedAt &&
                      ` · Published ${new Date(r.publishedAt).toLocaleDateString()}`}
                    {" · "}Seen by {r.seenCount}
                  </p>
                </div>
                <div className="flex shrink-0 gap-3 text-xs">
                  <button
                    className="text-slate-300 hover:text-white hover:underline"
                    onClick={() => setPreviewRow(r)}
                  >
                    Preview
                  </button>
                  {r.status === "DRAFT" ? (
                    <button
                      className="text-emerald-400 hover:underline"
                      onClick={() => doPublish(r.id)}
                    >
                      Publish
                    </button>
                  ) : (
                    <button
                      className="text-amber-400 hover:underline"
                      onClick={() => doUnpublish(r.id)}
                    >
                      Unpublish
                    </button>
                  )}
                  <button
                    className="text-red-400 hover:underline"
                    onClick={() => doDelete(r.id)}
                  >
                    Delete
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
      {/* Full-fidelity preview — mirrors components/customer/AnnouncementPopup.tsx's
          actual rendering exactly, so what you see here is what a customer sees. */}
      {previewRow &&
        typeof document !== "undefined" &&
        createPortal(
          <div
            className="fixed inset-0 z-[70] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"
            onClick={() => setPreviewRow(null)}
          >
            <div
              className="card w-full max-w-2xl overflow-hidden"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="border-b border-white/[0.06] bg-gradient-to-r from-brand-500/10 to-accent-blue/10 px-6 py-4">
                <div className="flex items-center gap-2">
                  <span className="flex h-6 w-6 items-center justify-center rounded-full bg-brand-500/20 text-brand-300">
                    ✦
                  </span>
                  <span className="text-xs font-medium uppercase tracking-wider text-brand-300">
                    What&apos;s new · admin preview
                  </span>
                </div>
                <h2 className="mt-2 text-lg font-bold tracking-tight text-white">
                  {previewRow.title}
                </h2>
                {previewRow.serviceTypes.length > 0 && (
                  <div className="mt-1.5 flex gap-1.5">
                    {previewRow.serviceTypes.map((t) => (
                      <span
                        key={t}
                        className="rounded border border-white/10 bg-white/[0.05] px-1.5 py-0.5 text-[10px] text-slate-400"
                      >
                        {t}
                      </span>
                    ))}
                  </div>
                )}
              </div>
              <div className="max-h-[60vh] overflow-y-auto px-6 py-5">
                {previewRow.gameFamilies.length > 0 && (
                  <div className="mb-4">
                    <p className="mb-2 text-[11px] font-medium uppercase tracking-wide text-slate-500">
                      {previewRow.gameFamilies.length > 1 ? "Games covered in this update" : "Game"}
                    </p>
                    <div className={`grid gap-2 ${previewRow.gameFamilies.length === 1 ? "grid-cols-3" : "grid-cols-4 sm:grid-cols-5"}`}>
                      {previewRow.gameFamilies.map((g) => (
                        <div key={g} className="overflow-hidden rounded-lg border border-white/10">
                          <GameCoverTile family={g} name={GAME_DISPLAY[g as keyof typeof GAME_DISPLAY]?.name ?? g} />
                          <p className="truncate bg-black/40 px-1.5 py-1 text-center text-[10px] font-medium text-slate-200">
                            {GAME_DISPLAY[g as keyof typeof GAME_DISPLAY]?.name ?? g}
                          </p>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                <div dangerouslySetInnerHTML={{ __html: renderMarkdown(previewRow.body) }} />
                {previewRow.screenshotUrl && (
                  <div className="mt-4">
                    {/* eslint-disable-next-line @next/next/no-img-element */}
                    <img
                      src={previewRow.screenshotUrl}
                      alt={`Screenshot for ${previewRow.title}`}
                      className="w-full rounded-xl border border-white/10 shadow-lg shadow-black/20"
                      loading="lazy"
                    />
                  </div>
                )}
              </div>
              <div className="flex items-center justify-between border-t border-white/[0.06] px-6 py-4">
                <span className="text-xs text-slate-500">
                  This is how it appears to a customer — the popup and What&apos;s New feed use identical markup.
                </span>
                <button className="btn-primary" onClick={() => setPreviewRow(null)}>
                  Close
                </button>
              </div>
            </div>
          </div>,
          document.body,
        )}
    </div>
  );
}

