  emailStartedAt  DateTime?
  emailFinishedAt DateTime?
  createdBy     String?
  publishedBy   String?
  deliveries    UpdateAnnouncementDelivery[]

  @@index([status, publishedAt])
}

// One row per (release, customer) announcement email — created BEFORE the send,
// so a crashed or overlapping sweep can never mail the same person twice.
model UpdateAnnouncementDelivery {
