/* What's New — pure rules (no database, no Next.js imports), shared by the
 * server actions, the worker's announcement-email sweep, the customer UI and
 * the tests. Everything that decides WHO sees a release, WHEN it is live, and
 * whether it counts as unread lives here, so the modal, the unread dot, the
 * changelog page, the admin preview and the email all agree by construction.
 */

// ---------------------------------------------------------------- categories

/** The changelog's filter row. Order is display order. */
export const WN_CATEGORIES = [
  "GAME_SERVERS",
  "VPS",
  "BILLING",
  "DASHBOARD",
  "SUPPORT",
  "PERFORMANCE",
] as const;
export type WnCategory = (typeof WN_CATEGORIES)[number];

export const WN_CATEGORY_META: Record<WnCategory, { label: string; tone: string }> = {
  GAME_SERVERS: { label: "Game servers", tone: "#22d3ee" },
  VPS: { label: "VPS", tone: "#3b82f6" },
  BILLING: { label: "Billing", tone: "#8a70fb" },
  DASHBOARD: { label: "Dashboard", tone: "#a86bff" },
  SUPPORT: { label: "Support", tone: "#34d399" },
  PERFORMANCE: { label: "Performance & reliability", tone: "#5fd0ff" },
};

export function isCategory(v: unknown): v is WnCategory {
  return typeof v === "string" && (WN_CATEGORIES as readonly string[]).includes(v);
}

/** Legacy rows carry serviceTypes instead of categories — map them across so
 *  old releases still filter sensibly on the new page. */
const LEGACY_SERVICE_TO_CATEGORY: Record<string, WnCategory> = {
  GAME: "GAME_SERVERS",
  VPS: "VPS",
  BILLING: "BILLING",
  PLATFORM: "DASHBOARD",
  HOSTING: "DASHBOARD",
  DOMAINS: "DASHBOARD",
  MAIL: "DASHBOARD",
};

// ---------------------------------------------------------------- highlights

export const WN_AVAILABILITY = ["LIVE", "NEXT_UPDATE"] as const;
export type WnAvailability = (typeof WN_AVAILABILITY)[number];

export type WnHighlight = {
  title: string;
  /** 1–2 lines, benefit first. Plain text (no Markdown, no HTML). */
  description: string;
  category: WnCategory;
  /** Relative path under /public, e.g. /whats-new/2026-10/chat.webp */
  imageUrl?: string | null;
  imageAlt?: string | null;
  /** "Try it" deep link — an in-app path, never an external URL. */
  ctaHref?: string | null;
  ctaLabel?: string | null;
  /** Admin-only: is this already live, or does it ship with the next deploy?
   *  Never shown to customers; publishing is refused while any item is
   *  NEXT_UPDATE (see publishBlockers). */
  availability: WnAvailability;
};

export const WN_LIMITS = {
  highlights: 12,
  title: 90,
  description: 260,
  ctaLabel: 28,
  alt: 200,
  path: 300,
  summary: 280,
} as const;

/** A safe in-app path: one leading slash, no scheme, no protocol-relative
 *  `//`, no backslashes or whitespace/control characters. */
export function isSafeRelativePath(p: unknown): p is string {
  if (typeof p !== "string") return false;
  if (!p.startsWith("/") || p.startsWith("//") || p.startsWith("/\\")) return false;
  if (p.length > WN_LIMITS.path) return false;
  // eslint-disable-next-line no-control-regex
  if (/[\s\\\u0000-\u001f<>"']/.test(p)) return false;
  return true;
}

/** Image paths must be under our own static folders. */
export function isSafeImagePath(p: unknown): p is string {
  return isSafeRelativePath(p) && /^\/(whats-new|uploads\/announcements|nx)\//.test(p) && !p.includes("..");
}

function clean(s: unknown, max: number): string {
  return String(s ?? "").replace(/\s+/g, " ").trim().slice(0, max);
}

export type ValidateResult = { ok: true; highlights: WnHighlight[] } | { ok: false; error: string };

/** Validate + normalise admin input. Rejects (never silently drops) a bad
 *  link or image, so an author always learns why something did not save. */
export function validateHighlights(input: unknown): ValidateResult {
  if (input == null) return { ok: true, highlights: [] };
  if (!Array.isArray(input)) return { ok: false, error: "Highlights must be a list." };
  if (input.length > WN_LIMITS.highlights) return { ok: false, error: `At most ${WN_LIMITS.highlights} highlights per release.` };
  const out: WnHighlight[] = [];
  for (let i = 0; i < input.length; i++) {
    const raw = (input[i] ?? {}) as Record<string, unknown>;
    const n = i + 1;
    const title = clean(raw.title, WN_LIMITS.title);
    const description = clean(raw.description, WN_LIMITS.description);
    if (!title) return { ok: false, error: `Highlight ${n}: add a title.` };
    if (!description) return { ok: false, error: `Highlight ${n}: add a short description.` };
    if (!isCategory(raw.category)) return { ok: false, error: `Highlight ${n}: pick a category.` };
    const imageUrl = raw.imageUrl ? String(raw.imageUrl).trim() : "";
    if (imageUrl && !isSafeImagePath(imageUrl)) {
      return { ok: false, error: `Highlight ${n}: image must be a path under /whats-new/ or /uploads/announcements/.` };
    }
    const ctaHref = raw.ctaHref ? String(raw.ctaHref).trim() : "";
    if (ctaHref && !isSafeRelativePath(ctaHref)) {
      return { ok: false, error: `Highlight ${n}: "Try it" link must be an in-app path such as /dashboard/games.` };
    }
    const imageAlt = clean(raw.imageAlt, WN_LIMITS.alt);
    if (imageUrl && !imageAlt) return { ok: false, error: `Highlight ${n}: describe the image (alt text) for screen readers.` };
    const availability: WnAvailability = raw.availability === "NEXT_UPDATE" ? "NEXT_UPDATE" : "LIVE";
    out.push({
      title,
      description,
      category: raw.category,
      imageUrl: imageUrl || null,
      imageAlt: imageAlt || null,
      ctaHref: ctaHref || null,
      ctaLabel: ctaHref ? clean(raw.ctaLabel, WN_LIMITS.ctaLabel) || "Try it" : null,
      availability,
    });
  }
  return { ok: true, highlights: out };
}

/** Parse a stored Json column defensively — a malformed row renders as a
 *  legacy body-only release instead of crashing the dashboard. */
export function parseStoredHighlights(json: unknown): WnHighlight[] {
  const r = validateHighlights(json);
  return r.ok ? r.highlights : [];
}

export function deriveCategories(highlights: WnHighlight[], legacyServiceTypes: string[] = []): WnCategory[] {
  const set = new Set<WnCategory>();
  for (const h of highlights) set.add(h.category);
  if (set.size === 0) for (const s of legacyServiceTypes) if (LEGACY_SERVICE_TO_CATEGORY[s]) set.add(LEGACY_SERVICE_TO_CATEGORY[s]);
  return WN_CATEGORIES.filter((c) => set.has(c));
}

// ---------------------------------------------------------------- lifecycle

export type WnStatus = "DRAFT" | "SCHEDULED" | "PUBLISHED";

export type WnLifecycleRow = {
  status: string;
  publishedAt: Date | null;
  scheduledFor: Date | null;
  createdAt: Date;
};

/** The status a customer experiences right now. A SCHEDULED release whose
 *  time has passed IS published — visibility never waits on a cron. */
export function effectiveStatus(row: WnLifecycleRow, now: Date): WnStatus {
  if (row.status === "PUBLISHED") return "PUBLISHED";
  if (row.status === "SCHEDULED") {
    if (row.scheduledFor && row.scheduledFor.getTime() <= now.getTime()) return "PUBLISHED";
    return "SCHEDULED";
  }
  return "DRAFT";
}

/** The date a live release shows (and sorts) by. */
export function liveDate(row: WnLifecycleRow): Date {
  if (row.status === "SCHEDULED" && row.scheduledFor) return row.scheduledFor;
  return row.publishedAt ?? row.createdAt;
}

/** Reasons the admin "Publish"/"Schedule" action must refuse. */
export function publishBlockers(input: { title: string; highlights: WnHighlight[]; body: string }): string[] {
  const out: string[] = [];
  if (!input.title.trim()) out.push("Add a release title.");
  if (input.highlights.length === 0 && !input.body.trim()) out.push("Add at least one highlight.");
  const pending = input.highlights.filter((h) => h.availability === "NEXT_UPDATE");
  if (pending.length) {
    out.push(
      `${pending.length} highlight${pending.length > 1 ? "s are" : " is"} marked "ships with the next update" (${pending
        .map((h) => h.title)
        .join(", ")}). Deploy first, then mark ${pending.length > 1 ? "them" : "it"} live.`,
    );
  }
  return out;
}

// ---------------------------------------------------------------- targeting

export const WN_AUDIENCES = ["ALL", "GAME", "VPS"] as const;
export type WnAudience = (typeof WN_AUDIENCES)[number];
export const WN_AUDIENCE_LABEL: Record<WnAudience, string> = {
  ALL: "All customers",
  GAME: "Game-server owners",
  VPS: "VPS owners",
};

export type WnTargetRow = { audience: string; regions: string[]; serviceTypes: string[] };

/** What we know about a customer for targeting. */
export type WnUserContext = {
  /** Service kinds they currently have: GAME, VPS, HOSTING, DOMAINS, MAIL, BILLING, PLATFORM. */
  services: string[];
  /** Region keys of their live servers. */
  regions: string[];
};

export function isVisibleTo(row: WnTargetRow, ctx: WnUserContext): boolean {
  const audience = (WN_AUDIENCES as readonly string[]).includes(row.audience) ? row.audience : "ALL";
  if (audience === "GAME" && !ctx.services.includes("GAME")) return false;
  if (audience === "VPS" && !ctx.services.includes("VPS")) return false;
  // Legacy service scoping (rows written before audiences existed).
  if (audience === "ALL" && row.serviceTypes.length > 0 && !row.serviceTypes.some((t) => ctx.services.includes(t))) {
    return false;
  }
  if (row.regions.length > 0 && !row.regions.some((r) => ctx.regions.includes(r))) return false;
  return true;
}

// ---------------------------------------------------------------- read state

export type WnSeen = { state: string; snoozedUntil: Date | null } | null;
export type WnReadState = "UNREAD" | "READ" | "SNOOZED";

/** Releases that went live before the account existed are not "new" to that
 *  customer — a fresh signup is not greeted by the whole back-catalogue. */
export function readState(seen: WnSeen, liveAt: Date, userCreatedAt: Date, now: Date): WnReadState {
  if (seen) {
    if (seen.state === "SNOOZED") {
      return seen.snoozedUntil && seen.snoozedUntil.getTime() > now.getTime() ? "SNOOZED" : "UNREAD";
    }
    return "READ";
  }
  if (liveAt.getTime() < userCreatedAt.getTime()) return "READ";
  return "UNREAD";
}

/** "Remind me later" = tomorrow. */
export const SNOOZE_MS = 24 * 60 * 60 * 1000;
export function snoozeUntil(now: Date): Date {
  return new Date(now.getTime() + SNOOZE_MS);
}

export type WnInboxItem = { id: string; liveAt: Date; state: WnReadState };

/** The unread dot counts UNREAD and SNOOZED (it is still unread — the customer
 *  only asked not to be interrupted). The modal auto-opens only for the newest
 *  UNREAD release; a snoozed one waits until its snooze passes. */
export function inboxSummary(items: WnInboxItem[]): { unread: number; autoOpenId: string | null } {
  const sorted = [...items].sort((a, b) => b.liveAt.getTime() - a.liveAt.getTime());
  const unread = sorted.filter((i) => i.state !== "READ").length;
  const newest = sorted[0];
  const autoOpenId = newest && newest.state === "UNREAD" ? newest.id : null;
  return { unread, autoOpenId };
}

// ---------------------------------------------------------------- email

/** Plain-text-safe HTML escape for the announcement email. */
export function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);
}

/** Should the email sweep pick this release up? */
export function emailDue(row: WnLifecycleRow & { emailAnnounce: boolean; emailFinishedAt: Date | null }, now: Date): boolean {
  return row.emailAnnounce && !row.emailFinishedAt && effectiveStatus(row, now) === "PUBLISHED";
}

