export type WnInboxItem = { id: string; liveAt: Date; state: WnReadState };

/** The unread dot counts UNREAD and SNOOZED (it is still unread — the customer
 *  only asked not to be interrupted). The modal auto-opens only for the newest
 *  UNREAD release; a snoozed one waits until its snooze passes. */
export function inboxSummary(items: WnInboxItem[]): { unread: number; autoOpenId: string | null } {
  const sorted = [...items].sort((a, b) => b.liveAt.getTime() - a.liveAt.getTime());
  const unread = sorted.filter((i) => i.state !== "READ").length;
  const newest = sorted[0];
  const autoOpenId = newest && newest.state === "UNREAD" ? newest.id : null;
  return { unread, autoOpenId };
}

// ---------------------------------------------------------------- email

/** Plain-text-safe HTML escape for the announcement email. */
export function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);
}

/** Should the email sweep pick this release up? */
export function emailDue(row: WnLifecycleRow & { emailAnnounce: boolean; emailFinishedAt: Date | null }, now: Date): boolean {
  return row.emailAnnounce && !row.emailFinishedAt && effectiveStatus(row, now) === "PUBLISHED";
}

