import { test, before, after } from "node:test";
import assert from "node:assert/strict";

/**
 * CUSTOM OFFERS — DB-backed half. Runs the REAL lib/offers.ts + lib/offer-fulfil.ts +
 * lib/fulfil-checkout.ts against a THROWAWAY Postgres with FAKE Stripe session objects
 * (fulfilRetrievedCheckoutSession) — no Stripe call is needed for the money logic.
 *
 * Opt-in and fail-closed, same guard as test/local-order-fulfilment.test.ts: runs only
 * when OFFERS_TEST_DATABASE_URL is set AND identical to DATABASE_URL AND points at
 * 127.0.0.1 on a non-default port with a database named `offers`. Otherwise skipped.
 *
 *   initdb a scratch cluster on e.g. :55471, createdb offers, then
 *   DATABASE_URL=postgresql://postgres@127.0.0.1:55471/offers OFFERS_TEST_DATABASE_URL=$DATABASE_URL \
 *     npx prisma db push --skip-generate && npx tsx --test test/offers-db.test.ts
 *
 * Proves: snapshot immutability, customer can only see their own (non-draft) offers,
 * idempotent fulfilment under concurrent wallet calls AND concurrent webhook+return
 * card calls (one server, one debit, one credit), a duplicate second payment is kept
 * as wallet credit + flagged, expiry (wallet refused; card honoured within grace only
 * if accepted in time), withdraw-during-checkout keeps the money safe, tampered terms
 * are refused, dedicated = invoice + task only, game offers, pinned node.
 */
const url = process.env.OFFERS_TEST_DATABASE_URL;
const safe = !!url && url === process.env.DATABASE_URL && /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:(?!5432\b)\d+\/offers$/.test(url);
const skip = safe ? false : "set OFFERS_TEST_DATABASE_URL (throwaway 127.0.0.1 /offers db) to run";

