  if (!safe) return;
  process.env.STRIPE_SECRET_KEY = "sk_test_fake_never_called";
  process.env.NXEON_HOST_RAM_MB = "100000000";
  delete process.env.SMTP_HOST;
  db = (await import("../lib/db.ts")).db;
  offers = await import("../lib/offers.ts");
  fulfil = await import("../lib/offer-fulfil.ts");
  checkout = await import("../lib/fulfil-checkout.ts");
  renewalCharge = (await import("../lib/renewal-charge.ts")).renewalCharge;
