/** Mark releases read. Only ids the customer can actually see are written, so a
 *  forged id can neither create rows for hidden drafts nor touch anyone else. */
export async function markRead(user: { id: string; createdAt: Date }, ids: string[], now = new Date()): Promise<number> {
  const want = new Set(ids.slice(0, 50));
  if (want.size === 0) return 0;
  const visible = (await listVisibleReleases(user, now)).filter((r) => want.has(r.id));
  for (const r of visible) {
    await db.userAnnouncementSeen.upsert({
      where: { userId_announcementId: { userId: user.id, announcementId: r.id } },
      create: { userId: user.id, announcementId: r.id, state: "READ" },
      update: { state: "READ", snoozedUntil: null, seenAt: now },
    });
  }
  return visible.length;
}

/** "Remind me later" — keeps the release unread (dot stays) but stops the
 *  modal opening by itself until tomorrow. Never downgrades a READ row. */
export async function snooze(user: { id: string; createdAt: Date }, id: string, now = new Date()): Promise<boolean> {
  const visible = (await listVisibleReleases(user, now)).find((r) => r.id === id);
  if (!visible || visible.state === "READ") return false;
  const until = snoozeUntil(now);
  await db.userAnnouncementSeen.upsert({
    where: { userId_announcementId: { userId: user.id, announcementId: id } },
    create: { userId: user.id, announcementId: id, state: "SNOOZED", snoozedUntil: until },
    update: { state: "SNOOZED", snoozedUntil: until },
  });
  return true;
}

// ---------------------------------------------------------------- admin

export type SaveInput = {
  id?: string | null;
  title: string;
  summary?: string | null;
  body?: string | null;
  kind?: string;
  heroImageUrl?: string | null;
  highlights?: unknown;
  audience?: string;
  regions?: string[];
  gameFamilies?: string[];
  emailAnnounce?: boolean;
};

const KINDS = ["FEATURE", "IMPROVEMENT", "BUGFIX"];

/** Create or update a release. Editing a PUBLISHED release is allowed (fix a
 *  typo) but never changes its status or date. */
export async function saveRelease(input: SaveInput, adminId: string | null, validRegions: string[]): Promise<{ id?: string; error?: string }> {
  const title = String(input.title ?? "").trim().slice(0, 200);
  if (!title) return { error: "Enter a release title." };
  const v = validateHighlights(input.highlights ?? []);
  if (!v.ok) return { error: v.error };
  const body = String(input.body ?? "").trim().slice(0, 10_000);
  if (v.highlights.length === 0 && !body) return { error: "Add at least one highlight." };
  const heroImageUrl = input.heroImageUrl ? String(input.heroImageUrl).trim() : "";
  if (heroImageUrl && !isSafeImagePath(heroImageUrl)) return { error: "Header image must be a path under /whats-new/ or /uploads/announcements/." };
  const audience = (WN_AUDIENCES as readonly string[]).includes(input.audience ?? "") ? input.audience! : "ALL";
  const regions = (input.regions ?? []).filter((r) => validRegions.includes(r));
  const data = {
    title,
    summary: String(input.summary ?? "").trim().slice(0, WN_LIMITS.summary) || null,
    body,
    kind: KINDS.includes(input.kind ?? "") ? input.kind! : "FEATURE",
    heroImageUrl: heroImageUrl || null,
    highlights: v.highlights as unknown as Prisma.InputJsonValue,
    categories: deriveCategories(v.highlights),
    audience,
    regions,
    // Audience replaces the old per-service checkboxes; GAME audience keeps the
    // legacy column in step so older readers of serviceTypes still agree.
    serviceTypes: audience === "ALL" ? [] : [audience],
    gameFamilies: (input.gameFamilies ?? []).slice(0, 60),
    emailAnnounce: !!input.emailAnnounce,
  };
  if (input.id) {
    const existing = await db.updateAnnouncement.findUnique({ where: { id: input.id }, select: { id: true, emailStartedAt: true } });
    if (!existing) return { error: "That release no longer exists." };
    // Once the email has started going out the toggle is history, not a setting.
    if (existing.emailStartedAt) delete (data as Partial<typeof data>).emailAnnounce;
    await db.updateAnnouncement.update({ where: { id: input.id }, data });
    return { id: input.id };
  }
  const created = await db.updateAnnouncement.create({ data: { ...data, status: "DRAFT", createdBy: adminId } });
  return { id: created.id };
}

async function loadForPublish(id: string) {
  const row = await db.updateAnnouncement.findUnique({ where: { id } });
  if (!row) return { error: "That release no longer exists." } as const;
  const blockers = publishBlockers({ title: row.title, body: row.body, highlights: parseStoredHighlights(row.highlights) });
  if (blockers.length) return { error: blockers.join(" ") } as const;
  return { row } as const;
}

export async function publishRelease(id: string, adminId: string | null, now = new Date()): Promise<{ error?: string }> {
  const r = await loadForPublish(id);
  if ("error" in r) return { error: r.error };
  await db.updateAnnouncement.update({
    where: { id },
    data: { status: "PUBLISHED", publishedAt: now, scheduledFor: null, publishedBy: adminId },
  });
  return {};
}

export async function scheduleRelease(id: string, when: Date, adminId: string | null, now = new Date()): Promise<{ error?: string }> {
  if (Number.isNaN(when.getTime())) return { error: "Pick a valid date and time." };
  if (when.getTime() <= now.getTime() + 60_000) return { error: "Pick a time at least a minute from now (or publish now)." };
  const r = await loadForPublish(id);
  if ("error" in r) return { error: r.error };
  await db.updateAnnouncement.update({
    where: { id },
    data: { status: "SCHEDULED", scheduledFor: when, publishedAt: null, publishedBy: adminId },
  });
  return {};
}

export async function unpublishRelease(id: string): Promise<void> {
  await db.updateAnnouncement.update({ where: { id }, data: { status: "DRAFT", scheduledFor: null } });
}

/** After a deploy: flip every "ships with the next update" item to live. */
export async function markAllLive(id: string): Promise<{ error?: string }> {
  const row = await db.updateAnnouncement.findUnique({ where: { id }, select: { highlights: true } });
  if (!row) return { error: "That release no longer exists." };
  const hs = parseStoredHighlights(row.highlights).map((h) => ({ ...h, availability: "LIVE" as const }));
  await db.updateAnnouncement.update({ where: { id }, data: { highlights: hs as unknown as Prisma.InputJsonValue } });
  return {};
}

// ---------------------------------------------------------------- email sweep

export type EmailSender = (to: { id: string; email: string; name: string }, release: WhatsNewRelease) => Promise<boolean>;

/**
 * Send announcement emails for live releases that asked for one. Idempotent per
 * recipient: the UpdateAnnouncementDelivery row is CLAIMED (unique insert)
 * before the send, so an overlapping or crashed sweep never mails anyone twice.
 * `perRun` caps one sweep; the next sweep continues where this one stopped.
 * The preference check (product_news) happens inside the real sender.
 */
export async function emailSweep(send: EmailSender, now = new Date(), perRun = 200): Promise<{ sent: number; skipped: number; done: string[] }> {
  const due = await db.updateAnnouncement.findMany({
    where: { emailAnnounce: true, emailFinishedAt: null, status: { in: ["PUBLISHED", "SCHEDULED"] } },
    take: 5,
  });
  let sent = 0, skipped = 0, budget = perRun;
  const done: string[] = [];
  for (const row of due) {
    if (effectiveStatus(row, now) !== "PUBLISHED") continue;
    if (!row.emailStartedAt) await db.updateAnnouncement.update({ where: { id: row.id }, data: { emailStartedAt: now } });
    let cursor: string | undefined;
    let exhausted = false;
    while (budget > 0) {
      const users = await db.user.findMany({
        where: { role: "CUSTOMER", suspended: false, emailVerifiedAt: { not: null }, deliveriesPending: undefined } as Prisma.UserWhereInput,
        select: { id: true, email: true, name: true, createdAt: true },
        orderBy: { id: "asc" },
        take: 100,
        ...(cursor ? { cursor: { id: cursor }, skip: 1 } : {}),
      });
      if (users.length === 0) { exhausted = true; break; }
      cursor = users[users.length - 1].id;
      const already = new Set(
        (await db.updateAnnouncementDelivery.findMany({
          where: { announcementId: row.id, userId: { in: users.map((u) => u.id) } },
          select: { userId: true },
        })).map((d) => d.userId),
      );
      for (const u of users) {
        if (budget <= 0) break;
        if (already.has(u.id)) continue;
        const ctx = await loadUserContext(u.id);
        const claimed = await db.updateAnnouncementDelivery
          .create({ data: { announcementId: row.id, userId: u.id } })
          .then(() => true, () => false);
        if (!claimed) continue;
        if (!isVisibleTo(row, ctx)) {
          await db.updateAnnouncementDelivery.updateMany({ where: { announcementId: row.id, userId: u.id }, data: { status: "SKIPPED" } });
          skipped++;
          continue;
        }
        budget--;
        const ok = await send(u, toRelease(row, "UNREAD")).catch(() => false);
        await db.updateAnnouncementDelivery.updateMany({
          where: { announcementId: row.id, userId: u.id },
          data: { status: ok ? "SENT" : "FAILED" },
        });
        if (ok) sent++;
      }
    }
    if (exhausted) {
      await db.updateAnnouncement.update({ where: { id: row.id }, data: { emailFinishedAt: now } });
      done.push(row.id);
    }
    if (budget <= 0) break;
  }
  return { sent, skipped, done };
}

