"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, impersonating } from "./auth";
import { requireArea } from "./rbac";
import { NODE_REGIONS } from "./node-regions";
import {
  inboxFor,
  listVisibleReleases,
  markAllLive,
  markRead,
  publishRelease,
  saveRelease,
  scheduleRelease,
  snooze,
  toRelease,
  unpublishRelease,
  type SaveInput,
  type WhatsNewRelease,
} from "./whats-new/data";
import { effectiveStatus, parseStoredHighlights } from "./whats-new/core";

/**
 * What's New — release notes pushed to customers (server actions).
 *
 * Lifecycle: DRAFT → (SCHEDULED →) PUBLISHED. Nothing reaches a customer until
 * an admin publishes or schedules it, and publishing is refused while any
 * highlight is still marked "ships with the next update". Targeting (audience +
 * region), read state and "remind me later" rules live in lib/whats-new/core.ts;
 * the queries in lib/whats-new/data.ts. Admin actions are area-gated
 * ("platform"); customer actions self-auth and only touch the caller's own rows.
 * While an admin is impersonating, customer read-state writes are skipped — the
 * admin must never mark a customer's updates as read for them.
 */

const ALL_REGIONS: string[] = Object.values(NODE_REGIONS).flat();

function revalidate() {
  revalidatePath("/admin/announcements");
  revalidatePath("/dashboard/whats-new");
}

// ---------- Admin ----------

export async function listAnnouncements() {
  await requireArea("platform");
  return db.updateAnnouncement.findMany({
    orderBy: { createdAt: "desc" },
    take: 200,
    include: { _count: { select: { seenBy: { where: { state: "READ" } }, deliveries: { where: { status: "SENT" } } } } },
  });
}

export async function saveAnnouncement(input: SaveInput): Promise<{ id?: string; error?: string }> {
  const admin = await requireArea("platform");
  const res = await saveRelease(input, admin.id, ALL_REGIONS);
  revalidate();
  return res;
}

export async function publishAnnouncement(id: string): Promise<{ error?: string }> {
  const admin = await requireArea("platform");
  const res = await publishRelease(id, admin.id);
  revalidate();
  return res;
}

export async function scheduleAnnouncement(id: string, iso: string): Promise<{ error?: string }> {
  const admin = await requireArea("platform");
  const res = await scheduleRelease(id, new Date(iso), admin.id);
  revalidate();
  return res;
}

export async function unpublishAnnouncement(id: string): Promise<void> {
  await requireArea("platform");
  await unpublishRelease(id);
  revalidate();
}

export async function markAnnouncementAllLive(id: string): Promise<{ error?: string }> {
  await requireArea("platform");
  const res = await markAllLive(id);
  revalidate();
  return res;
}

export async function deleteAnnouncement(id: string): Promise<void> {
  await requireArea("platform");
  await db.updateAnnouncement.delete({ where: { id } }).catch(() => undefined);
  revalidate();
}

/** Admin preview payload — any status, availability included. */
export async function getAnnouncementPreview(id: string): Promise<(WhatsNewRelease & { status: string }) | null> {
  await requireArea("platform");
  const row = await db.updateAnnouncement.findUnique({ where: { id } });
  if (!row) return null;
  const rel = toRelease(row, "UNREAD", { admin: true });
  // A draft has no live date yet — preview it as "today".
  if (effectiveStatus(row, new Date()) !== "PUBLISHED" && row.status !== "SCHEDULED") rel.liveAt = new Date().toISOString();
  return { ...rel, status: effectiveStatus(row, new Date()) };
}

// ---------- Customer ----------

/** The launcher's payload: newest releases, unread count, and which one (if
 *  any) should open by itself. Soft-fails to empty. */
export async function getWhatsNewInbox(): Promise<{ releases: WhatsNewRelease[]; unread: number; autoOpenId: string | null }> {
  const user = await requireUser();
  const inbox = await inboxFor(user);
  // Never pop a modal over an admin's impersonation session.
  if (await impersonating()) inbox.autoOpenId = null;
  return inbox;
}

/** The full changelog for this customer (only what they are targeted by). */
export async function getWhatsNew(): Promise<WhatsNewRelease[]> {
  const user = await requireUser();
  return listVisibleReleases(user);
}

export async function markReleasesRead(ids: string[]): Promise<void> {
  const user = await requireUser();
  if (await impersonating()) return;
  await markRead(user, Array.isArray(ids) ? ids.map(String) : []);
}

/** Kept for older callers: mark one release read. */
export async function markAnnouncementSeen(id: string): Promise<void> {
  await markReleasesRead([id]);
}

export async function remindMeLater(id: string): Promise<void> {
  const user = await requireUser();
  if (await impersonating()) return;
  await snooze(user, String(id));
}

/** Straight counts over the releases THIS customer can see. */
export async function getWhatsNewStats(): Promise<{ total: number; newThisMonth: number; highlights: number }> {
  const releases = await getWhatsNew();
  const monthStart = new Date();
  monthStart.setDate(1);
  monthStart.setHours(0, 0, 0, 0);
  return {
    total: releases.length,
    newThisMonth: releases.filter((r) => new Date(r.liveAt) >= monthStart).length,
    highlights: releases.reduce((n, r) => n + Math.max(1, r.highlights.length), 0),
  };
}

// keep the import used for type-only consumers
export type { WhatsNewRelease };
void parseStoredHighlights;

