"use client";

import Link from "next/link";
import { renderMarkdown } from "@/lib/blog";
import { WN_CATEGORY_META, isCategory, type WnCategory } from "@/lib/whats-new/core";
import type { WhatsNewRelease } from "@/lib/whats-new/data";
import { Icon } from "../Icon";

/* The pieces the release modal, the changelog page and the admin preview all
 * draw with — one set of markup, so the admin preview is what a customer sees
 * by construction rather than by a hand-kept copy. */

export function CategoryChip({ category }: { category: WnCategory | string }) {
  if (!isCategory(category)) return null;
  const meta = WN_CATEGORY_META[category];
  return (
    <span
      className="inline-flex items-center gap-1.5 rounded-full border px-2 py-0.5 text-[10.5px] font-bold uppercase tracking-[0.08em]"
      style={{ borderColor: `color-mix(in srgb, ${meta.tone} 40%, transparent)`, color: `color-mix(in srgb, ${meta.tone} 78%, var(--color-white))` }}
    >
      <span aria-hidden className="h-1.5 w-1.5 rounded-full" style={{ background: meta.tone }} />
      {meta.label}
    </span>
  );
}

/** Admin-preview-only: the owner sees which items are already live. */
export function AvailabilityBadge({ value }: { value?: string }) {
  if (!value) return null;
  return value === "LIVE" ? (
    <span className="rounded-full border border-emerald-500/50 bg-emerald-500/10 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-emerald-300">
      Live now
    </span>
  ) : (
    <span className="rounded-full border border-amber-500/50 bg-amber-500/10 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-amber-300">
      Ships with the next update
    </span>
  );
}

type Highlight = WhatsNewRelease["highlights"][number];

export function HighlightCard({
  h, onNavigate, compact = false, showAvailability = false,
}: {
  h: Highlight;
  onNavigate?: () => void;
  compact?: boolean;
  showAvailability?: boolean;
}) {
  return (
    <article className="group flex min-w-0 flex-col overflow-hidden rounded-[14px] border border-rim-hi bg-surface/60">
      {h.imageUrl && (
        // The frame is its own dark island: every image is a framed product
        // shot on the brand's navy ground, so it reads the same in both themes.
        <div className="nx-dark-island relative aspect-[16/9] w-full overflow-hidden bg-[#060a14]">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={h.imageUrl}
            alt={h.imageAlt ?? ""}
            width={1280}
            height={720}
            loading="lazy"
            decoding="async"
            className="h-full w-full object-cover motion-safe:transition-transform motion-safe:duration-500 motion-safe:group-hover:scale-[1.02]"
          />
        </div>
      )}
      <div className={"flex flex-1 flex-col gap-2 " + (compact ? "p-3.5" : "p-4")}>
        <div className="flex flex-wrap items-center gap-1.5">
          <CategoryChip category={h.category} />
          {showAvailability && <AvailabilityBadge value={h.availability} />}
        </div>
        <h4 className="text-[15px] font-extrabold leading-snug tracking-[-0.01em] text-white">{h.title}</h4>
        <p className="text-[13px] leading-[1.55] text-tx-mute">{h.description}</p>
        {h.ctaHref && (
          <Link
            href={h.ctaHref}
            onClick={onNavigate}
            className="mt-auto inline-flex w-fit items-center gap-1.5 pt-1 text-[12.5px] font-bold text-cyan underline-offset-4 hover:underline focus-visible:underline"
          >
            {h.ctaLabel || "Try it"}
            <span aria-hidden>→</span>
          </Link>
        )}
      </div>
    </article>
  );
}

/** Highlights grid, or the legacy Markdown body for releases written before
 *  highlights existed. */
export function ReleaseContent({
  release, onNavigate, compact = false, showAvailability = false,
}: {
  release: WhatsNewRelease;
  onNavigate?: () => void;
  compact?: boolean;
  showAvailability?: boolean;
}) {
  if (release.highlights.length === 0) {
    return (
      <div
        className="text-[13.5px] leading-[1.65] text-tx-mute [&_a]:text-cyan [&_h2]:text-white [&_h3]:text-white [&_strong]:text-white"
        dangerouslySetInnerHTML={{ __html: renderMarkdown(release.body) }}
      />
    );
  }
  return (
    <div className={"grid gap-3 " + (compact ? "sm:grid-cols-2" : "sm:grid-cols-2 xl:grid-cols-3")}>
      {release.highlights.map((h, i) => (
        <HighlightCard key={i} h={h} onNavigate={onNavigate} compact={compact} showAvailability={showAvailability} />
      ))}
    </div>
  );
}

export function ReleaseHero({ release, as: Tag = "h2", id }: { release: WhatsNewRelease; as?: "h1" | "h2" | "h3"; id?: string }) {
  const date = new Date(release.liveAt).toLocaleDateString(undefined, { month: "long", day: "numeric", year: "numeric" });
  return (
    <div className="flex flex-col gap-1.5">
      <span className="flex items-center gap-2 text-[11px] font-extrabold uppercase tracking-[0.2em] text-magenta">
        <Icon name="sparkles" size={13} tone="inherit" />
        What&apos;s new
        <span suppressHydrationWarning className="font-semibold normal-case tracking-normal text-tx-faint">· {date}</span>
      </span>
      <Tag id={id} className="text-[22px] font-extrabold leading-tight tracking-[-0.02em] text-white sm:text-[26px]">
        {release.title}
      </Tag>
      {release.summary && <p className="max-w-[64ch] text-[13.5px] leading-[1.6] text-tx-mute">{release.summary}</p>}
    </div>
  );
}

