"use client";

import { useEffect, useRef } from "react";
import { createPortal } from "react-dom";
import Link from "next/link";
import type { WhatsNewRelease } from "@/lib/whats-new/data";
import { Icon } from "../Icon";
import { ReleaseContent, ReleaseHero } from "./ReleaseParts";

/**
 * The latest-release dialog. A centred panel on desktop, a full-height sheet on
 * phones. Real dialog semantics: aria-modal, labelled by the release title,
 * focus moves in on open, Tab is kept inside, Esc closes, and focus goes back
 * to whatever opened it. Motion is entrance-only and `motion-safe:` gated, so
 * prefers-reduced-motion gets an instant, still dialog.
 *
 * Closing (X, Esc, backdrop, "Got it") counts as read; "Remind me later" keeps
 * it unread and stops it opening by itself until tomorrow.
 */
export function WhatsNewModal({
  release, onClose, onRemindLater, preview = false, showAvailability = false,
}: {
  release: WhatsNewRelease;
  onClose: () => void;
  onRemindLater?: () => void;
  /** Admin preview: draws inline (no portal / no backdrop close side effects). */
  preview?: boolean;
  showAvailability?: boolean;
}) {
  const panelRef = useRef<HTMLDivElement>(null);
  const restoreRef = useRef<HTMLElement | null>(null);

  useEffect(() => {
    restoreRef.current = (document.activeElement as HTMLElement) ?? null;
    const panel = panelRef.current;
    panel?.querySelector<HTMLElement>("[data-autofocus]")?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") { e.preventDefault(); onClose(); return; }
      if (e.key !== "Tab" || !panel) return;
      const f = [...panel.querySelectorAll<HTMLElement>('a[href],button:not([disabled]),[tabindex]:not([tabindex="-1"])')];
      if (f.length === 0) return;
      const first = f[0], last = f[f.length - 1];
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    };
    document.addEventListener("keydown", onKey);
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = prevOverflow;
      restoreRef.current?.focus?.();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  if (typeof document === "undefined") return null;

  const titleId = `wn-title-${release.id}`;
  const count = release.highlights.length;

  const ui = (
    <div className="fixed inset-0 z-[80] flex items-end justify-center sm:items-center sm:p-6" role="presentation">
      <button
        type="button"
        aria-label="Close what's new"
        tabIndex={-1}
        onClick={onClose}
        className="absolute inset-0 bg-black/70 backdrop-blur-sm motion-safe:animate-[wnFade_200ms_ease-out]"
      />
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        className="relative flex max-h-[100dvh] w-full flex-col overflow-hidden border border-rim-hi bg-bg shadow-2xl shadow-black/50 sm:max-h-[88dvh] sm:max-w-[880px] sm:rounded-[20px] motion-safe:animate-[wnRise_260ms_cubic-bezier(.2,.8,.2,1)]"
      >
        {/* header band */}
        <div className="relative overflow-hidden border-b border-rim-soft px-5 pb-4 pt-[calc(1rem+env(safe-area-inset-top))] sm:px-7 sm:pt-6">
          <span aria-hidden className="pointer-events-none absolute -right-24 -top-32 h-72 w-72 rounded-full bg-[radial-gradient(circle,rgba(123,63,239,0.35),transparent_65%)]" />
          <span aria-hidden className="pointer-events-none absolute -left-20 -top-24 h-56 w-56 rounded-full bg-[radial-gradient(circle,rgba(34,211,238,0.18),transparent_65%)]" />
          <div className="relative flex items-start gap-3">
            <div className="min-w-0 flex-1">
              <ReleaseHero release={release} id={titleId} />
              {count > 1 && (
                <p className="mt-2 text-[12px] font-semibold text-tx-faint">{count} highlights in this update</p>
              )}
            </div>
            <button
              type="button"
              onClick={onClose}
              aria-label="Close"
              className="grid h-10 w-10 flex-none place-items-center rounded-[10px] border border-rim-hi text-tx-dim transition hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-cyan"
            >
              <Icon name="xcircle" size={16} tone="inherit" />
            </button>
          </div>
        </div>

        {/* body */}
        <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-5 py-5 sm:px-7">
          {release.heroImageUrl && (
            <div className="nx-dark-island mb-4 overflow-hidden rounded-[14px] border border-rim-hi">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src={release.heroImageUrl} alt="" width={1600} height={520} className="aspect-[40/13] w-full object-cover" />
            </div>
          )}
          <ReleaseContent release={release} onNavigate={onClose} compact showAvailability={showAvailability} />
        </div>

        {/* footer */}
        <div className="flex flex-col-reverse gap-2 border-t border-rim-soft px-5 py-3.5 pb-[calc(0.875rem+env(safe-area-inset-bottom))] sm:flex-row sm:items-center sm:px-7">
          <Link
            href="/dashboard/whats-new"
            onClick={onClose}
            className="text-center text-[12.5px] font-semibold text-tx-mute underline-offset-4 hover:text-white hover:underline sm:mr-auto sm:text-left"
          >
            See all updates
          </Link>
          {onRemindLater && !preview && (
            <button type="button" onClick={onRemindLater} className="btn-ghost h-11 px-4 text-[13px]">
              Remind me later
            </button>
          )}
          <button type="button" data-autofocus onClick={onClose} className="btn-primary h-11 px-5 text-[13px]">
            Got it
          </button>
        </div>
      </div>
    </div>
  );

  return createPortal(ui, document.body);
}

