"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import { usePathname } from "next/navigation";
import { getWhatsNewInbox, markReleasesRead, remindMeLater } from "@/lib/actions-announcements";
import type { WhatsNewRelease } from "@/lib/whats-new/data";
import { Icon } from "../Icon";
import { WhatsNewModal } from "./WhatsNewModal";

/**
 * The topbar "What's new" entry point. A sparkles button with an unread dot
 * (only when something is unread — a dot that is always there teaches people
 * to ignore it), which opens the latest release. The newest unread release
 * opens by itself once; "Remind me later" postpones that until tomorrow.
 *
 * Fetches client-side after first paint so it never delays the dashboard, and
 * soft-fails to a plain button.
 */
export function WhatsNewLauncher() {
  const [releases, setReleases] = useState<WhatsNewRelease[]>([]);
  const [unread, setUnread] = useState(0);
  const [open, setOpen] = useState<WhatsNewRelease | null>(null);
  const [, start] = useTransition();
  const pathname = usePathname();

  useEffect(() => {
    let cancelled = false;
    getWhatsNewInbox()
      .then((inbox) => {
        if (cancelled) return;
        setReleases(inbox.releases);
        setUnread(inbox.unread);
        // Never interrupt someone already reading the changelog or the preview.
        if (inbox.autoOpenId && !(pathname ?? "").startsWith("/dashboard/whats-new")) {
          const r = inbox.releases.find((x) => x.id === inbox.autoOpenId);
          if (r) setOpen(r);
        }
      })
      .catch(() => {});
    return () => { cancelled = true; };
    // Once per dashboard mount, not per navigation.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const close = useCallback(() => {
    const r = open;
    setOpen(null);
    if (!r || r.state === "READ") return;
    setReleases((prev) => prev.map((x) => (x.id === r.id ? { ...x, state: "READ" } : x)));
    setUnread((n) => Math.max(0, n - 1));
    start(() => { markReleasesRead([r.id]).catch(() => {}); });
  }, [open]);

  const later = useCallback(() => {
    const r = open;
    setOpen(null);
    if (!r) return;
    setReleases((prev) => prev.map((x) => (x.id === r.id ? { ...x, state: "SNOOZED" } : x)));
    start(() => { remindMeLater(r.id).catch(() => {}); });
  }, [open]);

  const latest = releases[0];

  return (
    <>
      <button
        type="button"
        onClick={() => latest && setOpen(latest)}
        aria-label={unread > 0 ? `What's new: ${unread} unread update${unread > 1 ? "s" : ""}` : "What's new"}
        aria-haspopup="dialog"
        title="What's new"
        disabled={!latest}
        className="relative grid h-10 w-10 place-items-center rounded-[10px] text-tx-dim transition hover:bg-[rgba(72,148,255,0.08)] hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-cyan disabled:opacity-50"
      >
        <Icon name="sparkles" size={18} tone="inherit" />
        {unread > 0 && <span aria-hidden className="dot absolute right-2 top-2 bg-cyan text-cyan motion-safe:dot-live" />}
      </button>
      {open && (
        <WhatsNewModal
          release={open}
          onClose={close}
          onRemindLater={open.state !== "READ" ? later : undefined}
        />
      )}
    </>
  );
}

