"use client";

import { useEffect, useMemo, useRef, useState, useTransition } from "react";
import Link from "next/link";
import { markReleasesRead } from "@/lib/actions-announcements";
import type { WhatsNewRelease } from "@/lib/whats-new/data";
import { WN_CATEGORIES, WN_CATEGORY_META, type WnCategory } from "@/lib/whats-new/core";
import { Icon } from "./Icon";
import { Panel } from "./PageShell";
import { WhatsNewAurora } from "./WhatsNewAurora";
import { CategoryChip, ReleaseContent } from "./whatsnew/ReleaseParts";
import { WhatsNewModal } from "./whatsnew/WhatsNewModal";

/* The full changelog. Releases grouped by the day they went live, newest
 * first, filterable by category (a release shows only its matching highlights
 * under a filter) and searchable. A release scrolled into view for a moment
 * counts as read. Everything here is only what THIS customer is targeted by —
 * the same list the topbar launcher reads (lib/whats-new/data.ts).
 *
 * `preview` is the admin-only mode (/dashboard/whats-new/preview/[id]): the
 * draft is drawn at the top exactly as customers will see it, with the
 * owner-only "Live now / Ships with the next update" badges, the release
 * dialog opened over it, and no read-state writes.
 */
export function WhatsNewView({
  releases: initial, notifyOn, preview,
}: {
  releases: WhatsNewRelease[];
  notifyOn: boolean;
  preview?: { release: WhatsNewRelease; status: string };
}) {
  const [releases, setReleases] = useState(() =>
    preview ? [preview.release, ...initial.filter((r) => r.id !== preview.release.id)] : initial,
  );
  const [cat, setCat] = useState<WnCategory | "">("");
  const [q, setQ] = useState("");
  const [modal, setModal] = useState<WhatsNewRelease | null>(preview ? preview.release : null);
  const [, start] = useTransition();

  const filtered = useMemo(() => {
    const needle = q.trim().toLowerCase();
    return releases
      .map((r) => {
        if (r.highlights.length === 0) {
          const ok = (!cat || r.categories.includes(cat)) &&
            (!needle || r.title.toLowerCase().includes(needle) || r.body.toLowerCase().includes(needle));
          return ok ? r : null;
        }
        const hs = r.highlights.filter((h) =>
          (!cat || h.category === cat) &&
          (!needle || `${r.title} ${h.title} ${h.description}`.toLowerCase().includes(needle)));
        return hs.length ? { ...r, highlights: hs } : null;
      })
      .filter((r): r is WhatsNewRelease => r !== null);
  }, [releases, cat, q]);

  const groups = useMemo(() => {
    const map = new Map<string, WhatsNewRelease[]>();
    for (const r of filtered) {
      const key = new Date(r.liveAt).toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric", year: "numeric" });
      (map.get(key) ?? map.set(key, []).get(key)!).push(r);
    }
    return [...map.entries()];
  }, [filtered]);

  const unread = releases.filter((r) => r.state !== "READ").length;

  const markLocal = (ids: string[]) =>
    setReleases((prev) => prev.map((r) => (ids.includes(r.id) ? { ...r, state: "READ" } : r)));

  const markSeen = (id: string) => {
    if (preview) return;
    markLocal([id]);
    start(() => { markReleasesRead([id]).catch(() => {}); });
  };

  const markAll = () => {
    const ids = releases.filter((r) => r.state !== "READ").map((r) => r.id);
    if (!ids.length || preview) return;
    markLocal(ids);
    start(() => { markReleasesRead(ids).catch(() => {}); });
  };

  return (
    <>
      <WhatsNewAurora />
      <div className="relative mx-auto flex w-full max-w-[1320px] flex-col gap-5">
        {preview && (
          <div role="status" className="flex flex-wrap items-center gap-3 rounded-[14px] border border-amber-500/50 bg-amber-500/10 px-4 py-3 text-[12.5px] text-amber-200">
            <Icon name="eye" size={15} tone="inherit" />
            <span className="font-bold uppercase tracking-wide">Admin preview · {preview.status.toLowerCase()}</span>
            <span className="text-amber-100/80">
              This is exactly what targeted customers will see. The Live / Ships-with-next-update badges are only shown to you.
            </span>
            <button type="button" onClick={() => setModal(preview.release)} className="btn-ghost ml-auto h-9 px-3 text-[12px]">
              Open the dialog
            </button>
            <Link href="/admin/announcements" className="btn-ghost h-9 px-3 text-[12px]">Back to editor</Link>
          </div>
        )}

        {/* ── HERO ── */}
        <header className="relative flex flex-col gap-3 py-2">
          <span className="text-[12.5px] font-extrabold uppercase tracking-[0.24em] text-magenta">What&apos;s New</span>
          <h1 className="text-[34px] font-extrabold leading-[1.08] tracking-[-0.03em] text-white sm:text-[46px]">
            Everything new in{" "}
            <span className="bg-gradient-to-r from-[#5fd0ff] to-[#a23bff] bg-clip-text text-transparent">your Nxeon dashboard.</span>
          </h1>
          <p className="max-w-[60ch] text-[14px] leading-[1.6] text-tx-mute">
            New features, improvements and fixes, newest first. Each card links straight to the feature so you can try it.
          </p>
        </header>

        {/* ── FILTERS ── */}
        <div className="flex flex-col gap-2.5 lg:flex-row lg:items-center">
          <div role="group" aria-label="Filter by category" className="-mx-1 flex flex-1 gap-1.5 overflow-x-auto px-1 pb-1 [scrollbar-width:none] lg:flex-wrap lg:overflow-visible lg:pb-0">
            <button type="button" aria-pressed={cat === ""} onClick={() => setCat("")}
                    className={"chip h-[34px] flex-none px-3.5 text-[12.5px] " + (cat === "" ? "chip-on" : "")}>
              All updates
            </button>
            {WN_CATEGORIES.map((c) => (
              <button key={c} type="button" aria-pressed={cat === c} onClick={() => setCat(c)}
                      className={"chip h-[34px] flex-none px-3.5 text-[12.5px] " + (cat === c ? "chip-on" : "")}>
                <span aria-hidden className="mr-1.5 inline-block h-1.5 w-1.5 rounded-full" style={{ background: WN_CATEGORY_META[c].tone }} />
                {WN_CATEGORY_META[c].label}
              </button>
            ))}
          </div>
          <div className="flex items-center gap-2">
            <label className="field h-10 min-w-0 flex-1 lg:w-[240px] lg:flex-none">
              <Icon name="search" size={14} className="opacity-60" />
              <span className="sr-only">Search updates</span>
              <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search updates…"
                     className="min-w-0 flex-1 bg-transparent text-[13px] text-white outline-none placeholder:text-tx-faint" />
            </label>
            {unread > 0 && !preview && (
              <button type="button" onClick={markAll} className="btn-ghost h-10 flex-none px-3 text-[12px]">
                Mark all read
              </button>
            )}
          </div>
        </div>

        {/* ── BODY ── */}
        <div className="grid items-start gap-5 lg:grid-cols-[minmax(0,1fr)_260px]">
          <div className="flex min-w-0 flex-col gap-8">
            {groups.length === 0 ? (
              <div className="card card-glass flex flex-col items-center gap-3 py-14 text-center" style={{ "--tone": "#8c50ff" } as React.CSSProperties}>
                <Icon name="sparkles" size={22} className="opacity-60" />
                <span className="text-[13px] font-semibold text-white">
                  {releases.length === 0 ? "No updates yet" : "Nothing matches that filter."}
                </span>
                {releases.length === 0 ? (
                  <span className="text-[11.8px] text-tx-faint">We&apos;ll post here when there&apos;s something new.</span>
                ) : (
                  <button type="button" className="btn-ghost h-9 px-3 text-[12px]" onClick={() => { setCat(""); setQ(""); }}>Clear filters</button>
                )}
              </div>
            ) : (
              groups.map(([day, items]) => (
                <section key={day} aria-label={day}>
                  <h2 suppressHydrationWarning className="mb-3 flex items-center gap-3 text-[12px] font-extrabold uppercase tracking-[0.14em] text-cyan">
                    {day}
                    <span aria-hidden className="h-px flex-1 bg-rim-soft" />
                  </h2>
                  <div className="flex flex-col gap-4">
                    {items.map((r) => (
                      <ReleaseBlock key={r.id} release={r} onSeen={markSeen}
                                    showAvailability={!!preview && r.id === preview.release.id}
                                    onOpen={() => setModal(releases.find((x) => x.id === r.id) ?? r)} />
                    ))}
                  </div>
                </section>
              ))
            )}
          </div>

          <aside className="flex flex-col gap-3 lg:sticky lg:top-[88px]">
            <Panel className="card-glass" style={{ "--tone": "#8c50ff" } as React.CSSProperties}>
              <span className="flex items-center gap-2 text-[14px] font-extrabold tracking-[-0.02em] text-white">
                <Icon name="bellnotify" size={17} className="opacity-80" />
                Stay in the loop
              </span>
              <p className="mt-2 text-[11.8px] leading-[1.55] text-tx-mute">
                Product news emails are {notifyOn ? "on" : "off"} for your account. Change it any time in Settings.
              </p>
              <Link href="/dashboard/settings" className="btn-secondary mt-2.5 flex items-center justify-center py-1.5 text-[12px]">
                {notifyOn ? "Manage notifications" : "Turn on notifications"}
              </Link>
            </Panel>
            <Panel className="card-glass" style={{ "--tone": "#22d3ee" } as React.CSSProperties}>
              <span className="flex items-center gap-2 text-[14px] font-extrabold tracking-[-0.02em] text-white">
                <Icon name="chatdots" size={17} className="opacity-80" />
                Have a suggestion?
              </span>
              <p className="mt-2 text-[11.8px] leading-[1.55] text-tx-mute">
                Tell us what you would like next. Ideas from customers shape what we build.
              </p>
              <Link href="/dashboard/support" className="btn-ghost mt-2.5 flex items-center justify-center py-1.5 text-[12px]">
                Send feedback →
              </Link>
            </Panel>
          </aside>
        </div>
      </div>

      {modal && (
        <WhatsNewModal
          release={modal}
          preview={!!preview}
          showAvailability={!!preview && modal.id === preview.release.id}
          onClose={() => { const id = modal.id; setModal(null); markSeen(id); }}
        />
      )}
    </>
  );
}

function ReleaseBlock({
  release, onSeen, onOpen, showAvailability,
}: {
  release: WhatsNewRelease;
  onSeen: (id: string) => void;
  onOpen: () => void;
  showAvailability: boolean;
}) {
  const ref = useRef<HTMLElement>(null);
  const done = useRef(false);

  useEffect(() => {
    if (release.state === "READ" || done.current) return;
    const el = ref.current;
    if (!el || typeof IntersectionObserver === "undefined") return;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const io = new IntersectionObserver(([e]) => {
      if (e.isIntersecting) {
        timer = setTimeout(() => { done.current = true; onSeen(release.id); io.disconnect(); }, 1500);
      } else if (timer) {
        clearTimeout(timer);
      }
    }, { threshold: 0.35 });
    io.observe(el);
    return () => { io.disconnect(); if (timer) clearTimeout(timer); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [release.id, release.state]);

  return (
    <article ref={ref} aria-labelledby={`rel-${release.id}`} className="card card-glass p-4 sm:p-5" style={{ "--tone": "#7b3fef" } as React.CSSProperties}>
      <div className="mb-4 flex flex-wrap items-start gap-3">
        <div className="min-w-0 flex-1">
          <div className="mb-1.5 flex flex-wrap items-center gap-1.5">
            {release.state !== "READ" && <span className="badge badge-mint text-[10px]">New</span>}
            {release.categories.map((c) => <CategoryChip key={c} category={c} />)}
          </div>
          <h3 id={`rel-${release.id}`} className="text-[19px] font-extrabold leading-tight tracking-[-0.02em] text-white sm:text-[21px]">
            {release.title}
          </h3>
          {release.summary && <p className="mt-1 max-w-[70ch] text-[13px] leading-[1.6] text-tx-mute">{release.summary}</p>}
        </div>
        {release.highlights.length > 0 && (
          <button type="button" onClick={onOpen} className="btn-ghost h-9 flex-none px-3 text-[12px]">
            Open
          </button>
        )}
      </div>
      <ReleaseContent release={release} showAvailability={showAvailability} />
    </article>
  );
}

