"use client";

import { useEffect, useMemo, useRef, useState, useTransition } from "react";
import Link from "next/link";
import { markReleasesRead } from "@/lib/actions-announcements";
import type { WhatsNewRelease } from "@/lib/whats-new/data";
import { WN_CATEGORIES, WN_CATEGORY_META, type WnCategory } from "@/lib/whats-new/core";
