import { WhatsNewModal } from "./whatsnew/WhatsNewModal";

/* The full changelog. Releases grouped by the day they went live, newest
 * first, filterable by category (a release shows only its matching highlights
 * under a filter) and searchable. A release scrolled into view for a moment
 * counts as read. Everything here is only what THIS customer is targeted by —
 * the same list the topbar launcher reads (lib/whats-new/data.ts).
 *
 * `preview` is the admin-only mode (/dashboard/whats-new/preview/[id]): the
 * draft is drawn at the top exactly as customers will see it, with the
 * owner-only "Live now / Ships with the next update" badges, the release
 * dialog opened over it, and no read-state writes.
