  releases: initial, notifyOn, preview,
}: {
  releases: WhatsNewRelease[];
  notifyOn: boolean;
  preview?: { release: WhatsNewRelease; status: string; openDialog?: boolean };
}) {
  const [releases, setReleases] = useState(() =>
    preview ? [preview.release, ...initial.filter((r) => r.id !== preview.release.id)] : initial,
  );
  const [cat, setCat] = useState<WnCategory | "">("");
  const [q, setQ] = useState("");
  const [modal, setModal] = useState<WhatsNewRelease | null>(preview && preview.openDialog !== false ? preview.release : null);
  const [, start] = useTransition();

  const filtered = useMemo(() => {
    const needle = q.trim().toLowerCase();
    return releases
      .map((r) => {
        if (r.highlights.length === 0) {
          const ok = (!cat || r.categories.includes(cat)) &&
            (!needle || r.title.toLowerCase().includes(needle) || r.body.toLowerCase().includes(needle));
          return ok ? r : null;
        }
        const hs = r.highlights.filter((h) =>
          (!cat || h.category === cat) &&
          (!needle || `${r.title} ${h.title} ${h.description}`.toLowerCase().includes(needle)));
        return hs.length ? { ...r, highlights: hs } : null;
      })
      .filter((r): r is WhatsNewRelease => r !== null);
  }, [releases, cat, q]);

  const groups = useMemo(() => {
    const map = new Map<string, WhatsNewRelease[]>();
    for (const r of filtered) {
      const key = new Date(r.liveAt).toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric", year: "numeric" });
      (map.get(key) ?? map.set(key, []).get(key)!).push(r);
    }
    return [...map.entries()];
  }, [filtered]);

  const unread = releases.filter((r) => r.state !== "READ").length;

  const markLocal = (ids: string[]) =>
    setReleases((prev) => prev.map((r) => (ids.includes(r.id) ? { ...r, state: "READ" } : r)));

  const markSeen = (id: string) => {
    if (preview) return;
    markLocal([id]);
    start(() => { markReleasesRead([id]).catch(() => {}); });
  };

