    <article ref={ref} aria-labelledby={`rel-${release.id}`} className="card card-glass p-4 sm:p-5" style={{ "--tone": "#7b3fef" } as React.CSSProperties}>
      <div className="mb-4 flex flex-wrap items-start gap-3">
        <div className="min-w-0 flex-1">
          <div className="mb-1.5 flex flex-wrap items-center gap-1.5">
            {release.state !== "READ" && <span className="badge badge-mint text-[10px]">New</span>}
            {release.categories.map((c) => <CategoryChip key={c} category={c} />)}
          </div>
          <h3 id={`rel-${release.id}`} className="text-[19px] font-extrabold leading-tight tracking-[-0.02em] text-white sm:text-[21px]">
            {release.title}
          </h3>
          {release.summary && <p className="mt-1 max-w-[70ch] text-[13px] leading-[1.6] text-tx-mute">{release.summary}</p>}
