import { notFound } from "next/navigation";
import { requireArea } from "@/lib/rbac";
import { getAnnouncementPreview, getWhatsNew } from "@/lib/actions-announcements";
import { normalizePrefs } from "@/lib/prefs";
import { WhatsNewView } from "@/components/nx/WhatsNewView";

export const dynamic = "force-dynamic";

/* Admin-only preview of any release (draft, scheduled or live), drawn by the
 * real customer components inside the real dashboard shell: the changelog with
 * this release on top and its dialog opened. Gated by requireArea("platform")
 * (redirects anyone else away), and it writes no read state. `?dialog=0`
 * starts with the dialog closed (for screenshots of the page alone). */
export default async function WhatsNewPreviewPage({
  params, searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ dialog?: string }>;
}) {
  const admin = await requireArea("platform");
  const { id } = await params;
  const { dialog } = await searchParams;
  const release = await getAnnouncementPreview(id);
  if (!release) notFound();
  const others = await getWhatsNew().catch(() => []);
  const { status, ...rel } = release;
  return (
    <WhatsNewView
      releases={others}
      notifyOn={normalizePrefs(admin.notificationPrefs).product}
      preview={{ release: rel, status, openDialog: dialog !== "0" }}
    />
  );
}
EOF
