"use client";

import { useMemo, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  saveAnnouncement,
  publishAnnouncement,
  scheduleAnnouncement,
  unpublishAnnouncement,
  deleteAnnouncement,
  markAnnouncementAllLive,
} from "@/lib/actions-announcements";
import {
  WN_AUDIENCES,
  WN_AUDIENCE_LABEL,
  WN_CATEGORIES,
  WN_CATEGORY_META,
  WN_LIMITS,
  publishBlockers,
  validateHighlights,
  type WnHighlight,
} from "@/lib/whats-new/core";
import type { WhatsNewRelease } from "@/lib/whats-new/data";
import { ReleaseContent, ReleaseHero } from "@/components/nx/whatsnew/ReleaseParts";

export type AdminRow = {
  id: string;
  title: string;
  summary: string | null;
  body: string;
  kind: string;
  heroImageUrl: string | null;
  highlights: WnHighlight[];
  categories: string[];
  audience: string;
  regions: string[];
  gameFamilies: string[];
  emailAnnounce: boolean;
  emailStartedAt: string | null;
  emailFinishedAt: string | null;
  status: string; // effective: DRAFT | SCHEDULED | PUBLISHED
  scheduledFor: string | null;
  publishedAt: string | null;
  createdAt: string;
  readCount: number;
  emailedCount: number;
};

type Draft = {
  id: string | null;
  title: string;
  summary: string;
  body: string;
  heroImageUrl: string;
  audience: string;
  regions: string[];
  gameFamilies: string[];
  emailAnnounce: boolean;
  highlights: WnHighlight[];
};

const EMPTY_HIGHLIGHT: WnHighlight = {
  title: "", description: "", category: "DASHBOARD", imageUrl: "", imageAlt: "", ctaHref: "", ctaLabel: "Try it", availability: "LIVE",
};

const blank = (): Draft => ({
  id: null, title: "", summary: "", body: "", heroImageUrl: "", audience: "ALL", regions: [], gameFamilies: [], emailAnnounce: false,
  highlights: [{ ...EMPTY_HIGHLIGHT }],
});

const STATUS_BADGE: Record<string, string> = {
  DRAFT: "border-amber-500/40 bg-amber-500/10 text-amber-300",
  SCHEDULED: "border-sky-500/40 bg-sky-500/10 text-sky-300",
  PUBLISHED: "border-emerald-500/40 bg-emerald-500/10 text-emerald-300",
};

/**
 * The What's New editor. One form for create + edit; a live preview beside it
 * drawn with the SAME components the customer dialog and changelog use
 * (components/nx/whatsnew/ReleaseParts.tsx), plus a full in-dashboard preview
 * URL per release. Publishing is refused while any highlight is still marked
 * "ships with the next update"; the announcement email is opt-in and off by
 * default.
 */
export function AnnouncementsAdmin({ rows, regions }: { rows: AdminRow[]; regions: { key: string; label: string }[] }) {
  const router = useRouter();
  const [d, setD] = useState<Draft>(blank);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<{ tone: "err" | "ok"; text: string } | null>(null);
  const [when, setWhen] = useState<Record<string, string>>({});

  const set = <K extends keyof Draft>(k: K, v: Draft[K]) => setD((p) => ({ ...p, [k]: v }));
  const setH = (i: number, patch: Partial<WnHighlight>) =>
    setD((p) => ({ ...p, highlights: p.highlights.map((h, j) => (j === i ? { ...h, ...patch } : h)) }));
  const moveH = (i: number, dir: -1 | 1) =>
    setD((p) => {
      const hs = [...p.highlights];
      const j = i + dir;
      if (j < 0 || j >= hs.length) return p;
      [hs[i], hs[j]] = [hs[j], hs[i]];
      return { ...p, highlights: hs };
    });

  const filled = useMemo(() => d.highlights.filter((h) => h.title || h.description), [d.highlights]);
  const formCheck = useMemo(() => validateHighlights(filled), [filled]);

  // Live preview from the form — validated the same way the server will.
  const previewRelease: WhatsNewRelease = useMemo(() => ({
    id: d.id ?? "new", title: d.title || "Untitled release", summary: d.summary || null, body: d.body,
    heroImageUrl: d.heroImageUrl || null,
    highlights: formCheck.ok ? formCheck.highlights : filled.filter((h) => h.title),
    categories: [], gameFamilies: d.gameFamilies, liveAt: new Date().toISOString(), state: "UNREAD",
  }), [d, filled, formCheck]);

  const blockers = useMemo(
    () => publishBlockers({ title: d.title, body: d.body, highlights: formCheck.ok ? formCheck.highlights : [] }),
    [d.title, d.body, formCheck],
  );

  function edit(r: AdminRow) {
    setD({
      id: r.id, title: r.title, summary: r.summary ?? "", body: r.body, heroImageUrl: r.heroImageUrl ?? "",
      audience: r.audience, regions: r.regions, gameFamilies: r.gameFamilies, emailAnnounce: r.emailAnnounce,
      highlights: r.highlights.map((h) => ({ ...EMPTY_HIGHLIGHT, ...h })),
    });
    setMsg(null);
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  async function save() {
    setBusy(true);
    setMsg(null);
    const res = await saveAnnouncement({
      id: d.id, title: d.title, summary: d.summary, body: d.body, heroImageUrl: d.heroImageUrl || null,
      audience: d.audience, regions: d.regions, gameFamilies: d.gameFamilies, emailAnnounce: d.emailAnnounce,
      highlights: filled,
    });
    setBusy(false);
    if (res.error) return setMsg({ tone: "err", text: res.error });
    setD((p) => ({ ...p, id: res.id ?? p.id }));
    setMsg({ tone: "ok", text: "Saved. A draft is invisible to customers until you publish or schedule it." });
    router.refresh();
  }

  async function act(fn: () => Promise<{ error?: string } | void>, ok: string) {
    setMsg(null);
    const res = (await fn()) as { error?: string } | undefined;
    if (res?.error) setMsg({ tone: "err", text: res.error });
    else setMsg({ tone: "ok", text: ok });
    router.refresh();
  }

  function publish(r: AdminRow) {
    const mail = r.emailAnnounce ? "\n\nThe announcement EMAIL is ON for this release: targeted customers who allow product news will be emailed." : "";
    if (!confirm(`Publish "${r.title}" to customers now?${mail}`)) return;
    act(() => publishAnnouncement(r.id), "Published.");
  }

  return (
    <div className="space-y-6">
      {/* ── Editor + live preview ── */}
      <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
        <div className="card space-y-4">
          <div className="flex items-center justify-between gap-2">
            <p className="text-sm font-semibold text-white">{d.id ? "Edit release" : "New release"}</p>
            {d.id && (
              <button type="button" className="text-xs text-slate-400 hover:text-white" onClick={() => { setD(blank()); setMsg(null); }}>
                + Start a new one
              </button>
            )}
          </div>

          <label className="block space-y-1">
            <span className="text-xs font-medium text-slate-400">Release title</span>
            <input className="input" maxLength={200} value={d.title} onChange={(e) => set("title", e.target.value)}
                   placeholder="e.g. Faster setup, easier mods, and a better live chat" />
          </label>
          <label className="block space-y-1">
            <span className="text-xs font-medium text-slate-400">Summary (one line, optional)</span>
            <input className="input" maxLength={WN_LIMITS.summary} value={d.summary} onChange={(e) => set("summary", e.target.value)} />
          </label>
          <label className="block space-y-1">
            <span className="text-xs font-medium text-slate-400">Header image (optional, /whats-new/… path)</span>
            <input className="input text-sm" value={d.heroImageUrl} onChange={(e) => set("heroImageUrl", e.target.value)} placeholder="/whats-new/2026-10-release/header.webp" />
          </label>

          {/* Targeting */}
          <fieldset className="space-y-2 rounded-xl border border-white/[0.06] p-3">
            <legend className="px-1 text-xs font-medium text-slate-400">Who sees it</legend>
            <div className="flex flex-wrap gap-4">
              {WN_AUDIENCES.map((a) => (
                <label key={a} className="flex items-center gap-1.5 text-sm text-slate-300">
                  <input type="radio" name="audience" className="accent-brand-500" checked={d.audience === a} onChange={() => set("audience", a)} />
                  {WN_AUDIENCE_LABEL[a]}
                </label>
              ))}
            </div>
            <details className="text-sm text-slate-300" open={d.regions.length > 0}>
              <summary className="cursor-pointer text-xs text-slate-400">Limit to regions {d.regions.length ? `(${d.regions.length})` : "(optional)"}</summary>
              <p className="mt-1 text-[11px] text-slate-500">Only customers with a server in one of these regions. Leave empty for every region.</p>
              <div className="mt-2 flex flex-wrap gap-3">
                {regions.map((r) => (
                  <label key={r.key} className="flex items-center gap-1.5 text-xs">
                    <input type="checkbox" className="accent-brand-500" checked={d.regions.includes(r.key)}
                           onChange={() => set("regions", d.regions.includes(r.key) ? d.regions.filter((x) => x !== r.key) : [...d.regions, r.key])} />
                    {r.label}
                  </label>
                ))}
              </div>
            </details>
          </fieldset>

          {/* Highlights */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-xs font-medium text-slate-400">Highlights ({d.highlights.length}/{WN_LIMITS.highlights}) — one card each, benefit first</span>
              <div className="flex gap-3 text-xs">
                {d.highlights.some((h) => h.availability === "NEXT_UPDATE") && (
                  <button type="button" className="text-emerald-400 hover:underline"
                          onClick={() => set("highlights", d.highlights.map((h) => ({ ...h, availability: "LIVE" })))}>
                    Mark all live
                  </button>
                )}
                <button type="button" className="text-brand-300 hover:underline" disabled={d.highlights.length >= WN_LIMITS.highlights}
                        onClick={() => set("highlights", [...d.highlights, { ...EMPTY_HIGHLIGHT }])}>
                  + Add highlight
                </button>
              </div>
            </div>
            {d.highlights.map((h, i) => (
              <div key={i} className="space-y-2 rounded-xl border border-white/[0.08] bg-black/20 p-3">
                <div className="flex items-center gap-2">
                  <span className="text-[11px] font-bold text-slate-500">#{i + 1}</span>
                  <input className="input h-9 flex-1 text-sm" placeholder="Title" aria-label={`Highlight ${i + 1} title`} maxLength={WN_LIMITS.title} value={h.title} onChange={(e) => setH(i, { title: e.target.value })} />
                  <button type="button" aria-label="Move up" className="px-1 text-slate-400 hover:text-white" onClick={() => moveH(i, -1)}>↑</button>
                  <button type="button" aria-label="Move down" className="px-1 text-slate-400 hover:text-white" onClick={() => moveH(i, 1)}>↓</button>
                  <button type="button" aria-label="Remove" className="px-1 text-red-400 hover:text-red-300" onClick={() => set("highlights", d.highlights.filter((_, j) => j !== i))}>✕</button>
                </div>
                <textarea className="input min-h-[64px] text-sm" placeholder="1–2 lines. Lead with what the customer gets." aria-label={`Highlight ${i + 1} description`} maxLength={WN_LIMITS.description}
                          value={h.description} onChange={(e) => setH(i, { description: e.target.value })} />
                <p className="text-right text-[10px] text-slate-500">{h.description.length}/{WN_LIMITS.description}</p>
                <div className="grid gap-2 sm:grid-cols-2">
                  <select className="input h-9 text-sm" value={h.category} onChange={(e) => setH(i, { category: e.target.value as WnHighlight["category"] })} aria-label="Category">
                    {WN_CATEGORIES.map((c) => <option key={c} value={c}>{WN_CATEGORY_META[c].label}</option>)}
                  </select>
                  <select className="input h-9 text-sm" value={h.availability} onChange={(e) => setH(i, { availability: e.target.value as WnHighlight["availability"] })} aria-label="Availability">
                    <option value="LIVE">Live now</option>
                    <option value="NEXT_UPDATE">Ships with the next update</option>
                  </select>
                  <input className="input h-9 text-sm" placeholder="Image path /whats-new/…" aria-label="Image path" value={h.imageUrl ?? ""} onChange={(e) => setH(i, { imageUrl: e.target.value })} />
                  <input className="input h-9 text-sm" placeholder="Image alt text (required with an image)" aria-label="Image alt text" value={h.imageAlt ?? ""} onChange={(e) => setH(i, { imageAlt: e.target.value })} />
                  <input className="input h-9 text-sm" placeholder='"Try it" link, e.g. /dashboard/games' aria-label="Try it link" value={h.ctaHref ?? ""} onChange={(e) => setH(i, { ctaHref: e.target.value })} />
                  <input className="input h-9 text-sm" placeholder="Link label (default: Try it)" aria-label="Link label" maxLength={WN_LIMITS.ctaLabel} value={h.ctaLabel ?? ""} onChange={(e) => setH(i, { ctaLabel: e.target.value })} />
                </div>
              </div>
            ))}
          </div>

          <details>
            <summary className="cursor-pointer text-xs text-slate-400">Extra notes (Markdown, optional — shown only when a release has no highlights)</summary>
            <textarea className="input mt-2 min-h-[90px] font-mono text-xs" value={d.body} onChange={(e) => set("body", e.target.value)} maxLength={10000} />
          </details>

          <label className="flex items-start gap-2 rounded-xl border border-white/[0.06] p-3 text-sm text-slate-300">
            <input type="checkbox" className="mt-0.5 accent-brand-500" checked={d.emailAnnounce} onChange={(e) => set("emailAnnounce", e.target.checked)} />
            <span>
              Also send an announcement email
              <span className="block text-[11px] text-slate-500">
                Off by default. Sent once, after the release goes live, only to verified customers it targets who allow product news. Cannot be recalled once sending starts.
              </span>
            </span>
          </label>

          {!formCheck.ok && <p className="text-xs text-amber-300">{formCheck.error}</p>}
          {blockers.length > 0 && formCheck.ok && <p className="text-xs text-slate-400">Before publishing: {blockers.join(" ")}</p>}
          <div className="flex flex-wrap items-center gap-3">
            <button className="btn-primary" onClick={save} disabled={busy || !d.title.trim()}>
              {busy ? "Saving…" : d.id ? "Save changes" : "Save draft"}
            </button>
            {d.id && (
              <Link href={`/dashboard/whats-new/preview/${d.id}`} target="_blank" className="text-xs text-slate-300 hover:text-white hover:underline">
                Open full preview ↗
              </Link>
            )}
          </div>
          {msg && <p className={"text-sm " + (msg.tone === "err" ? "text-red-400" : "text-emerald-400")}>{msg.text}</p>}
        </div>

        <div className="card space-y-3 xl:sticky xl:top-4 xl:self-start">
          <p className="text-xs font-medium uppercase tracking-wide text-slate-500">Live preview — same components customers see</p>
          <div className="space-y-4 rounded-xl border border-white/[0.06] bg-bg p-4">
            <ReleaseHero release={previewRelease} as="h3" />
            <ReleaseContent release={previewRelease} compact showAvailability />
          </div>
          <p className="text-[11px] text-slate-500">
            &ldquo;Open full preview&rdquo; shows this release inside the real customer dashboard (dialog + changelog), visible only to admins.
          </p>
        </div>
      </div>

      {/* ── List ── */}
      <div className="card p-0">
        <div className="border-b border-white/[0.06] px-4 py-3 text-sm font-semibold text-white">Releases ({rows.length})</div>
        {rows.length === 0 ? (
          <p className="px-4 py-6 text-sm text-slate-400">No releases yet.</p>
        ) : (
          <ul className="divide-y divide-white/[0.06]">
            {rows.map((r) => {
              const pending = r.highlights.filter((h) => h.availability === "NEXT_UPDATE").length;
              return (
                <li key={r.id} className="flex flex-col gap-3 px-4 py-4 lg:flex-row lg:items-start">
                  <div className="min-w-0 flex-1">
                    <p className="flex flex-wrap items-center gap-2 text-sm font-medium text-slate-100">
                      <span className="truncate">{r.title}</span>
                      <span className={`rounded-full border px-2 py-0.5 text-[10px] font-medium ${STATUS_BADGE[r.status] ?? STATUS_BADGE.DRAFT}`}>{r.status.toLowerCase()}</span>
                      {pending > 0 && <span className="rounded-full border border-amber-500/40 px-2 py-0.5 text-[10px] text-amber-300">{pending} ship with next update</span>}
                      {r.emailAnnounce && <span className="rounded-full border border-fuchsia-500/40 px-2 py-0.5 text-[10px] text-fuchsia-300">email on</span>}
                    </p>
                    <p className="mt-1 text-[11px] text-slate-500">
                      {WN_AUDIENCE_LABEL[r.audience as keyof typeof WN_AUDIENCE_LABEL] ?? r.audience}
                      {r.regions.length > 0 && ` · ${r.regions.join(", ")}`}
                      {` · ${r.highlights.length || 1} card${r.highlights.length === 1 ? "" : "s"}`}
                      {` · created ${new Date(r.createdAt).toLocaleDateString()}`}
                      {r.status === "SCHEDULED" && r.scheduledFor && ` · goes live ${new Date(r.scheduledFor).toLocaleString()}`}
                      {r.status === "PUBLISHED" && r.publishedAt && ` · published ${new Date(r.publishedAt).toLocaleDateString()}`}
                      {` · read by ${r.readCount}`}
                      {r.emailStartedAt && ` · emailed ${r.emailedCount}${r.emailFinishedAt ? " (done)" : " (sending)"}`}
                    </p>
                  </div>
                  <div className="flex flex-wrap items-center gap-3 text-xs">
                    <button className="text-slate-300 hover:text-white hover:underline" onClick={() => edit(r)}>Edit</button>
                    <Link className="text-slate-300 hover:text-white hover:underline" href={`/dashboard/whats-new/preview/${r.id}`} target="_blank">Preview ↗</Link>
                    {pending > 0 && (
                      <button className="text-emerald-400 hover:underline" onClick={() => act(() => markAnnouncementAllLive(r.id), "All highlights marked live.")}>Mark all live</button>
                    )}
                    {r.status !== "PUBLISHED" && (
                      <>
                        <button className="text-emerald-400 hover:underline" onClick={() => publish(r)}>Publish now</button>
                        <span className="flex items-center gap-1">
                          <input type="datetime-local" aria-label="Schedule for" className="input h-8 w-[190px] text-xs"
                                 value={when[r.id] ?? ""} onChange={(e) => setWhen((p) => ({ ...p, [r.id]: e.target.value }))} />
                          <button className="text-sky-400 hover:underline disabled:opacity-40" disabled={!when[r.id]}
                                  onClick={() => act(() => scheduleAnnouncement(r.id, new Date(when[r.id]).toISOString()), "Scheduled.")}>
                            Schedule
                          </button>
                        </span>
                      </>
                    )}
                    {r.status !== "DRAFT" && (
                      <button className="text-amber-400 hover:underline" onClick={() => act(() => unpublishAnnouncement(r.id), "Moved back to draft.")}>
                        {r.status === "SCHEDULED" ? "Cancel schedule" : "Unpublish"}
                      </button>
                    )}
                    <button className="text-red-400 hover:underline"
                            onClick={() => { if (confirm("Delete this release permanently?")) act(() => deleteAnnouncement(r.id), "Deleted."); }}>
                      Delete
                    </button>
                  </div>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </div>
  );
}

