import { requireArea } from "@/lib/rbac";
import { PageHeader } from "@/components/ui/primitives";
import { listAnnouncements } from "@/lib/actions-announcements";
import { AnnouncementsAdmin } from "@/components/admin/AnnouncementsAdmin";
import { effectiveStatus, parseStoredHighlights } from "@/lib/whats-new/core";
import { NODE_REGIONS, customerRegionLabel } from "@/lib/node-regions";

export const dynamic = "force-dynamic";

export default async function AdminAnnouncementsPage() {
  await requireArea("platform");
  const rows = await listAnnouncements();
  const now = new Date();
  const regions = Object.values(NODE_REGIONS).flat().map((key) => ({ key, label: `${customerRegionLabel(key)} (${key})` }));
  return (
    <div className="space-y-6">
      <PageHeader
        title="What's New"
        sub="Customer release notes. Drafts are private; a published (or scheduled, once its time passes) release shows in the dashboard's What's new dialog and changelog for the customers it targets. Customer-facing changes only — never internal admin tooling."
      />
      <AnnouncementsAdmin
        regions={regions}
        rows={rows.map((r) => ({
          id: r.id,
          title: r.title,
          summary: r.summary,
          body: r.body,
          kind: r.kind,
          heroImageUrl: r.heroImageUrl,
          highlights: parseStoredHighlights(r.highlights),
          categories: r.categories,
          audience: r.audience,
          regions: r.regions,
          gameFamilies: r.gameFamilies,
          emailAnnounce: r.emailAnnounce,
          emailStartedAt: r.emailStartedAt?.toISOString() ?? null,
          emailFinishedAt: r.emailFinishedAt?.toISOString() ?? null,
          status: effectiveStatus(r, now),
          scheduledFor: r.scheduledFor?.toISOString() ?? null,
          publishedAt: r.publishedAt?.toISOString() ?? null,
          createdAt: r.createdAt.toISOString(),
          readCount: r._count.seenBy,
          emailedCount: r._count.deliveries,
        }))}
      />
    </div>
  );
}

