// What's New announcement email sweep.
//
// Sends the ONE optional announcement email for a live release whose author
// ticked "Also send an announcement email" (UpdateAnnouncement.emailAnnounce,
// default OFF). The recipient rules and per-recipient idempotency live in
// lib/whats-new/data.ts (emailSweep): verified customers the release targets,
// one UpdateAnnouncementDelivery row claimed before each send so nobody is
// mailed twice. This file only renders and sends: product_news tier, so the
// customer's "product news" preference is honoured by sendMail itself, with a
// one-click unsubscribe header like every other marketing send.
import { sendMail } from "../lib/mailer";
import { appUrl, emailButton, emailEyebrow, emailHeading, emailList, emailParagraph, wrapEmail } from "../lib/email-render";
import { marketingUnsubUrl } from "../lib/marketing-unsub";
import { emailSweep } from "../lib/whats-new/data";
import { escapeHtml } from "../lib/whats-new/core";

const SEND_GAP_MS = 250;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

export async function whatsNewEmailSweep(): Promise<void> {
  const base = appUrl();
  const res = await emailSweep(async (u, release) => {
    const unsub = marketingUnsubUrl(u.id);
    const items = release.highlights.slice(0, 8).map((h) => `<strong>${escapeHtml(h.title)}</strong> — ${escapeHtml(h.description)}`);
    const html = wrapEmail(
      [
        emailEyebrow("What's new"),
        emailHeading(escapeHtml(release.title)),
        release.summary ? emailParagraph(escapeHtml(release.summary)) : "",
        items.length ? emailList(items) : "",
        emailButton(`${base}/dashboard/whats-new`, "See what's new"),
        emailParagraph(`<span style="font-size:12px;opacity:.7">You get this because product news is on for your account. <a href="${unsub}">Unsubscribe</a>.</span>`),
      ].join(""),
      { preheader: release.summary ?? release.title },
    );
    const ok = await sendMail({
      to: u.email,
      subject: `What's new at Nxeon: ${release.title}`,
      html,
      listUnsubscribeUrl: unsub,
      userId: u.id,
      kind: "product_news",
    });
    await sleep(SEND_GAP_MS);
    return ok;
  });
  if (res.sent || res.done.length) console.log(`[whats-new-email] sent ${res.sent}, skipped ${res.skipped}, finished ${res.done.length}`);
}
EOF
