import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync, existsSync } from "node:fs";
import path from "node:path";
import {
  deriveCategories,
  effectiveStatus,
  emailDue,
  inboxSummary,
  isSafeImagePath,
  isSafeRelativePath,
  isVisibleTo,
  liveDate,
  publishBlockers,
  readState,
  snoozeUntil,
  validateHighlights,
  SNOOZE_MS,
} from "../lib/whats-new/core";

const now = new Date("2026-10-06T12:00:00Z");
const earlier = new Date("2026-10-01T00:00:00Z");
const later = new Date("2026-10-07T00:00:00Z");

const H = (o: Record<string, unknown> = {}) => ({
  title: "Download folders",
  description: "Grab a whole folder as one archive.",
  category: "GAME_SERVERS",
  availability: "LIVE",
  ...o,
});

// ---------------------------------------------------------------- validation

test("validateHighlights: normalises a good card and defaults the link label", () => {
  const r = validateHighlights([H({ ctaHref: "/dashboard/games", imageUrl: "/whats-new/x/a.webp", imageAlt: "Files tab" })]);
  assert.ok(r.ok);
  assert.equal(r.highlights[0].ctaLabel, "Try it");
  assert.equal(r.highlights[0].availability, "LIVE");
});

test("validateHighlights: refuses external / protocol-relative / script links", () => {
  for (const href of ["https://evil.test", "//evil.test", "javascript:alert(1)", "/\\evil", "/a b", '/a"onmouseover'])
    assert.equal(validateHighlights([H({ ctaHref: href })]).ok, false, href);
});

test("validateHighlights: image must be ours and carry alt text", () => {
  assert.equal(validateHighlights([H({ imageUrl: "https://cdn.test/a.png", imageAlt: "x" })]).ok, false);
  assert.equal(validateHighlights([H({ imageUrl: "/whats-new/../etc/passwd", imageAlt: "x" })]).ok, false);
  assert.equal(validateHighlights([H({ imageUrl: "/whats-new/r/a.webp" })]).ok, false, "alt required");
  assert.ok(validateHighlights([H({ imageUrl: "/whats-new/r/a.webp", imageAlt: "A thing" })]).ok);
});

test("validateHighlights: category required, unknown availability becomes LIVE, cap enforced", () => {
  assert.equal(validateHighlights([H({ category: "SEO" })]).ok, false);
  const r = validateHighlights([H({ availability: "weird" })]);
  assert.ok(r.ok && r.highlights[0].availability === "LIVE");
  assert.equal(validateHighlights(Array.from({ length: 13 }, () => H())).ok, false);
  assert.equal(validateHighlights("nope").ok, false);
});

test("safe path helpers", () => {
  assert.ok(isSafeRelativePath("/dashboard/directory?game=rust"));
  assert.equal(isSafeRelativePath("dashboard"), false);
  assert.ok(isSafeImagePath("/uploads/announcements/a.png"));
  assert.equal(isSafeImagePath("/dashboard/a.png"), false);
});

test("deriveCategories: from highlights in display order, else from legacy serviceTypes", () => {
  const r = validateHighlights([H({ category: "SUPPORT" }), H({ category: "GAME_SERVERS" }), H({ category: "SUPPORT" })]);
  assert.ok(r.ok);
  assert.deepEqual(deriveCategories(r.highlights), ["GAME_SERVERS", "SUPPORT"]);
  assert.deepEqual(deriveCategories([], ["VPS", "PLATFORM"]), ["VPS", "DASHBOARD"]);
});

// ---------------------------------------------------------------- lifecycle

const row = (o: Partial<{ status: string; publishedAt: Date | null; scheduledFor: Date | null; createdAt: Date }>) => ({
  status: "DRAFT", publishedAt: null, scheduledFor: null, createdAt: earlier, ...o,
});

test("effectiveStatus: drafts never leak, scheduled goes live by itself", () => {
  assert.equal(effectiveStatus(row({}), now), "DRAFT");
  assert.equal(effectiveStatus(row({ status: "SCHEDULED", scheduledFor: later }), now), "SCHEDULED");
  assert.equal(effectiveStatus(row({ status: "SCHEDULED", scheduledFor: earlier }), now), "PUBLISHED");
  assert.equal(effectiveStatus(row({ status: "SCHEDULED", scheduledFor: null }), now), "SCHEDULED");
  assert.equal(effectiveStatus(row({ status: "PUBLISHED", publishedAt: earlier }), now), "PUBLISHED");
  assert.equal(effectiveStatus(row({ status: "garbage" }), now), "DRAFT");
});

test("liveDate: scheduled time, else publishedAt, else createdAt", () => {
  assert.equal(liveDate(row({ status: "SCHEDULED", scheduledFor: later })).getTime(), later.getTime());
  assert.equal(liveDate(row({ status: "PUBLISHED", publishedAt: now })).getTime(), now.getTime());
  assert.equal(liveDate(row({})).getTime(), earlier.getTime());
});

test("publishBlockers: refuses while anything ships with the next update", () => {
  const r = validateHighlights([H(), H({ title: "Mods tab", availability: "NEXT_UPDATE" })]);
  assert.ok(r.ok);
  const b = publishBlockers({ title: "Oct", body: "", highlights: r.highlights });
  assert.equal(b.length, 1);
  assert.match(b[0], /Mods tab/);
  assert.deepEqual(publishBlockers({ title: "Oct", body: "", highlights: [r.highlights[0]] }), []);
  assert.equal(publishBlockers({ title: "", body: "", highlights: [] }).length, 2);
  assert.deepEqual(publishBlockers({ title: "Legacy", body: "some **markdown**", highlights: [] }), []);
});

// ---------------------------------------------------------------- targeting

const ctx = (services: string[], regions: string[] = []) => ({ services: ["BILLING", "PLATFORM", ...services], regions });

test("isVisibleTo: audiences", () => {
  const all = { audience: "ALL", regions: [], serviceTypes: [] };
  assert.ok(isVisibleTo(all, ctx([])));
  assert.equal(isVisibleTo({ ...all, audience: "GAME" }, ctx(["VPS"])), false);
  assert.ok(isVisibleTo({ ...all, audience: "GAME" }, ctx(["GAME"])));
  assert.equal(isVisibleTo({ ...all, audience: "VPS" }, ctx(["GAME"])), false);
  assert.ok(isVisibleTo({ ...all, audience: "VPS" }, ctx(["VPS", "GAME"])));
  assert.ok(isVisibleTo({ ...all, audience: "bogus" }, ctx([])), "unknown audience = all");
});

test("isVisibleTo: regions intersect, legacy serviceTypes still scope", () => {
  const sgp = { audience: "ALL", regions: ["sgp1"], serviceTypes: [] };
  assert.equal(isVisibleTo(sgp, ctx(["GAME"], ["fsn1"])), false);
  assert.ok(isVisibleTo(sgp, ctx(["GAME"], ["fsn1", "sgp1"])));
  assert.equal(isVisibleTo(sgp, ctx([], [])), false, "no servers = no region");
  const legacy = { audience: "ALL", regions: [], serviceTypes: ["HOSTING"] };
  assert.equal(isVisibleTo(legacy, ctx(["GAME"])), false);
  assert.ok(isVisibleTo(legacy, ctx(["HOSTING"])));
  assert.ok(isVisibleTo({ audience: "ALL", regions: [], serviceTypes: ["BILLING"] }, ctx([])), "BILLING is everyone");
});

// ---------------------------------------------------------------- read state

test("readState: unread, read, snoozed and expired snooze", () => {
  const signup = earlier;
  assert.equal(readState(null, now, signup, now), "UNREAD");
  assert.equal(readState({ state: "READ", snoozedUntil: null }, now, signup, now), "READ");
  assert.equal(readState({ state: "SNOOZED", snoozedUntil: later }, now, signup, now), "SNOOZED");
  assert.equal(readState({ state: "SNOOZED", snoozedUntil: earlier }, now, signup, now), "UNREAD");
  assert.equal(readState({ state: "SNOOZED", snoozedUntil: null }, now, signup, now), "UNREAD");
});

test("readState: releases from before signup are not 'new' to that account", () => {
  assert.equal(readState(null, earlier, now, now), "READ");
});

test("snoozeUntil is one day", () => {
  assert.equal(snoozeUntil(now).getTime() - now.getTime(), SNOOZE_MS);
  assert.equal(SNOOZE_MS, 86_400_000);
});

test("inboxSummary: dot counts unread + snoozed; auto-open only the newest UNREAD", () => {
  const a = { id: "a", liveAt: earlier, state: "UNREAD" as const };
  const b = { id: "b", liveAt: now, state: "SNOOZED" as const };
  const c = { id: "c", liveAt: later, state: "READ" as const };
  assert.deepEqual(inboxSummary([a, b]), { unread: 2, autoOpenId: null }, "newest is snoozed: do not pop the older one");
  assert.deepEqual(inboxSummary([a]), { unread: 1, autoOpenId: "a" });
  assert.deepEqual(inboxSummary([a, c]), { unread: 1, autoOpenId: null }, "newest already read");
  assert.deepEqual(inboxSummary([]), { unread: 0, autoOpenId: null });
});

test("emailDue: only opted-in, live, unfinished releases", () => {
  const live = { ...row({ status: "PUBLISHED", publishedAt: earlier }), emailAnnounce: true, emailFinishedAt: null };
  assert.ok(emailDue(live, now));
  assert.equal(emailDue({ ...live, emailAnnounce: false }, now), false, "default OFF never sends");
  assert.equal(emailDue({ ...live, emailFinishedAt: now }, now), false);
  assert.equal(emailDue({ ...live, status: "DRAFT" }, now), false);
  assert.equal(emailDue({ ...live, status: "SCHEDULED", publishedAt: null, scheduledFor: later }, now), false);
});

// ---------------------------------------------------------------- the draft release

test("draft release seed: valid, customer-only, unpublished, images exist", () => {
  const file = path.join(__dirname, "..", "prisma", "whats-new", "2026-10-release.json");
  const seed = JSON.parse(readFileSync(file, "utf8"));
  assert.equal(seed.status, "DRAFT");
  assert.equal(seed.emailAnnounce, false);
  const r = validateHighlights(seed.highlights);
  assert.ok(r.ok, r.ok ? "" : r.error);
  for (const h of r.highlights) {
    assert.ok(h.imageUrl, `${h.title} has a graphic`);
    assert.ok(existsSync(path.join(__dirname, "..", "public", h.imageUrl!)), `${h.imageUrl} exists`);
  }
  if (seed.heroImageUrl) assert.ok(existsSync(path.join(__dirname, "..", "public", seed.heroImageUrl)));
  const text = JSON.stringify(seed).toLowerCase();
  // Owner exclusions + brand voice: none of these may appear in a customer update.
  for (const banned of ["ovh", "provider", "invoice", "status notice", "custom offer", "theme", "light/dark", "dark mode", "admin"]) {
    assert.equal(text.includes(banned), false, `must not mention "${banned}"`);
  }
  // Publishing must be refused until the not-yet-deployed items are marked live.
  assert.ok(publishBlockers({ title: seed.title, body: "", highlights: r.highlights }).length > 0);
});

