test("isVisibleTo: regions intersect, legacy serviceTypes still scope", () => {
  const sgp = { audience: "ALL", regions: ["sgp1"], serviceTypes: [] };
  assert.equal(isVisibleTo(sgp, ctx(["GAME"], ["fsn1"])), false);
  assert.ok(isVisibleTo(sgp, ctx(["GAME"], ["fsn1", "sgp1"])));
  assert.equal(isVisibleTo(sgp, ctx([], [])), false, "no servers = no region");
  const legacy = { audience: "ALL", regions: [], serviceTypes: ["HOSTING"] };
  assert.equal(isVisibleTo(legacy, ctx(["GAME"])), false);
  assert.ok(isVisibleTo(legacy, ctx(["HOSTING"])));
  assert.ok(isVisibleTo({ audience: "ALL", regions: [], serviceTypes: ["BILLING"] }, ctx([])), "BILLING is everyone");
});

// ---------------------------------------------------------------- read state

test("readState: unread, read, snoozed and expired snooze", () => {
  const signup = earlier;
  assert.equal(readState(null, now, signup, now), "UNREAD");
  assert.equal(readState({ state: "READ", snoozedUntil: null }, now, signup, now), "READ");
  assert.equal(readState({ state: "SNOOZED", snoozedUntil: later }, now, signup, now), "SNOOZED");
  assert.equal(readState({ state: "SNOOZED", snoozedUntil: earlier }, now, signup, now), "UNREAD");
  assert.equal(readState({ state: "SNOOZED", snoozedUntil: null }, now, signup, now), "UNREAD");
});

test("readState: releases from before signup are not 'new' to that account", () => {
  assert.equal(readState(null, earlier, now, now), "READ");
});

test("snoozeUntil is one day", () => {
  assert.equal(snoozeUntil(now).getTime() - now.getTime(), SNOOZE_MS);
  assert.equal(SNOOZE_MS, 86_400_000);
});

test("inboxSummary: dot counts unread + snoozed; auto-open only the newest UNREAD", () => {
  const a = { id: "a", liveAt: earlier, state: "UNREAD" as const };
  const b = { id: "b", liveAt: now, state: "SNOOZED" as const };
  const c = { id: "c", liveAt: later, state: "READ" as const };
  assert.deepEqual(inboxSummary([a, b]), { unread: 2, autoOpenId: null }, "newest is snoozed: do not pop the older one");
  assert.deepEqual(inboxSummary([a]), { unread: 1, autoOpenId: "a" });
  assert.deepEqual(inboxSummary([a, c]), { unread: 1, autoOpenId: null }, "newest already read");
  assert.deepEqual(inboxSummary([]), { unread: 0, autoOpenId: null });
});

test("emailDue: only opted-in, live, unfinished releases", () => {
  const live = { ...row({ status: "PUBLISHED", publishedAt: earlier }), emailAnnounce: true, emailFinishedAt: null };
  assert.ok(emailDue(live, now));
  assert.equal(emailDue({ ...live, emailAnnounce: false }, now), false, "default OFF never sends");
  assert.equal(emailDue({ ...live, emailFinishedAt: now }, now), false);
  assert.equal(emailDue({ ...live, status: "DRAFT" }, now), false);
  assert.equal(emailDue({ ...live, status: "SCHEDULED", publishedAt: null, scheduledFor: later }, now), false);
});

// ---------------------------------------------------------------- the draft release

test("draft release seed: valid, customer-only, unpublished, images exist", () => {
  const file = path.join(__dirname, "..", "prisma", "whats-new", "2026-10-release.json");
  const seed = JSON.parse(readFileSync(file, "utf8"));
  assert.equal(seed.status, "DRAFT");
  assert.equal(seed.emailAnnounce, false);
  const r = validateHighlights(seed.highlights);
  assert.ok(r.ok, r.ok ? "" : r.error);
  for (const h of r.highlights) {
    assert.ok(h.imageUrl, `${h.title} has a graphic`);
    assert.ok(existsSync(path.join(__dirname, "..", "public", h.imageUrl!)), `${h.imageUrl} exists`);
  }
  if (seed.heroImageUrl) assert.ok(existsSync(path.join(__dirname, "..", "public", seed.heroImageUrl)));
  const text = JSON.stringify(seed).toLowerCase();
  // Owner exclusions + brand voice: none of these may appear in a customer update.
  for (const banned of ["ovh", "provider", "invoice", "status notice", "custom offer", "theme", "light/dark", "dark mode", "admin"]) {
    assert.equal(text.includes(banned), false, `must not mention "${banned}"`);
  }
  // Publishing must be refused until the not-yet-deployed items are marked live.
  assert.ok(publishBlockers({ title: seed.title, body: "", highlights: r.highlights }).length > 0);
});

