/**
 * Load a What's New release file (prisma/whats-new/*.json) as a DRAFT.
 *
 *   npx tsx prisma/seed-whats-new.ts prisma/whats-new/2026-10-release.json
 *
 * - Always a DRAFT: nothing reaches a customer until an admin publishes it in
 *   /admin/announcements (and publishing is refused while any highlight is still
 *   marked "ships with the next update").
 * - Email is forced OFF here; turn it on in the editor if you want it.
 * - Idempotent: re-running updates the existing DRAFT with the same title
 *   instead of creating a second one. It never touches a published release.
 * - Refuses the production database (port 5432, database "nxeon") unless
 *   --allow-prod is passed explicitly.
 */
import { readFileSync } from "node:fs";
import { db } from "../lib/db";
import { saveRelease } from "../lib/whats-new/data";
import { NODE_REGIONS } from "../lib/node-regions";

async function main() {
  const file = process.argv.slice(2).find((a) => !a.startsWith("--"));
  if (!file) throw new Error("usage: tsx prisma/seed-whats-new.ts <release.json> [--allow-prod]");
  const url = process.env.DATABASE_URL ?? "";
  const looksProd = /@(localhost|127\.0\.0\.1):5432\/nxeon(\?|$)/.test(url);
  if (looksProd && !process.argv.includes("--allow-prod")) {
    throw new Error("Refusing to write to the production database. Pass --allow-prod to load the draft there on purpose.");
  }
  const rel = JSON.parse(readFileSync(file, "utf8"));
  const existing = await db.updateAnnouncement.findFirst({ where: { title: rel.title }, select: { id: true, status: true } });
  if (existing && existing.status !== "DRAFT") throw new Error(`"${rel.title}" already exists as ${existing.status}; not touching it.`);
  const res = await saveRelease(
    {
      id: existing?.id ?? null,
      title: rel.title,
      summary: rel.summary,
      body: rel.body ?? "",
      heroImageUrl: rel.heroImageUrl ?? null,
      highlights: rel.highlights,
      audience: rel.audience ?? "ALL",
      regions: rel.regions ?? [],
      emailAnnounce: false,
    },
    null,
    Object.values(NODE_REGIONS).flat(),
  );
  if (res.error) throw new Error(res.error);
  console.log(`${existing ? "Updated" : "Created"} DRAFT ${res.id}: ${rel.title}`);
  console.log(`Preview (admin only): /dashboard/whats-new/preview/${res.id}`);
}

main()
  .catch((e) => { console.error(e instanceof Error ? e.message : e); process.exitCode = 1; })
  .finally(() => db.$disconnect());
EOF
