import { test, before, after } from "node:test";
import assert from "node:assert/strict";

/**
 * WHAT'S NEW — DB-backed half. Runs the REAL lib/whats-new/data.ts against a
 * THROWAWAY Postgres. Opt-in and fail-closed: runs only when
 * WHATSNEW_TEST_DATABASE_URL is set, identical to DATABASE_URL, and points at
 * 127.0.0.1 on a non-default port with a database named `whatsnew`.
 *
 *   initdb a scratch cluster on e.g. :55481, createdb whatsnew, then
 *   DATABASE_URL=postgresql://postgres@127.0.0.1:55481/whatsnew WHATSNEW_TEST_DATABASE_URL=$DATABASE_URL \
 *     npx prisma db push --skip-generate && npx tsx --test test/whats-new-db.test.ts
 *
 * Proves: drafts and future schedules never reach a customer; publish is
 * refused while an item ships with the next update; audience + region
 * targeting against real Server/Node rows; read / snooze / expiry; forged ids
 * are ignored; releases from before signup are not "new"; the email sweep
 * only mails opted-in releases, only targeted verified customers, exactly once
 * even when run twice.
 */
const url = process.env.WHATSNEW_TEST_DATABASE_URL;
const safe = !!url && url === process.env.DATABASE_URL && /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:(?!5432\b)\d+\/whatsnew$/.test(url);
const skip = safe ? false : "set WHATSNEW_TEST_DATABASE_URL (throwaway 127.0.0.1 /whatsnew db) to run";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
let wn: typeof import("../lib/whats-new/data.ts");
const RUN = Date.now().toString(36);
const T0 = new Date("2026-09-01T00:00:00Z");
const NOW = new Date("2026-10-06T12:00:00Z");

type U = { id: string; createdAt: Date };
let gamer: U, vpsUser: U, nobody: U, fresh: U;

const H = (o: Record<string, unknown> = {}) => ({
  title: "Folder downloads", description: "Grab a folder as one archive.", category: "GAME_SERVERS", availability: "LIVE", ...o,
});

before(async () => {
  if (!safe) return;
  db = (await import("../lib/db.ts")).db;
  wn = await import("../lib/whats-new/data.ts");
  // Throwaway DB only (guarded above): start from a clean slate for these tables.
  await db.updateAnnouncementDelivery.deleteMany({});
  await db.userAnnouncementSeen.deleteMany({});
  await db.updateAnnouncement.deleteMany({});

  const mkUser = async (tag: string, createdAt: Date, verified = true) =>
    db.user.create({
      data: { email: `${tag}-${RUN}@example.test`, passwordHash: "x", name: tag, createdAt, emailVerifiedAt: verified ? createdAt : null },
      select: { id: true, createdAt: true },
    });
  gamer = await mkUser("gamer", T0);
  vpsUser = await mkUser("vps", T0);
  nobody = await mkUser("nobody", T0, false);
  fresh = await mkUser("fresh", new Date("2026-10-05T00:00:00Z"));

  const plan = await db.plan.create({ data: { slug: `p-${RUN}`, name: "p", cpuCores: 1, ramMB: 1024, diskGB: 10, priceCents: 100 } });
  const gp = await db.gamePlan.create({ data: { gameFamily: "minecraft", name: "mc", ramMB: 1024, diskGB: 10, priceCents: 100, basePlanId: plan.id } });
  const os = await db.osTemplate.create({ data: { slug: `os-${RUN}`, name: "Ubuntu", vmid: 9000 } });
  const node = (region: string) => db.node.create({
    data: { name: `n-${region}-${RUN}`, pveNode: "pve", apiUrl: "https://127.0.0.1:8006", tokenId: "t", tokenSecret: "s", publicIp: "192.0.2.1", region },
  });
  const sgp = await node("sgp1");
  const fsn = await node("fsn1");
  const server = (userId: string, nodeId: string, gamePlanId: string | null, status: "RUNNING" | "DELETING" = "RUNNING") =>
    db.server.create({
      data: { name: "s", hostname: `h-${Math.random().toString(36).slice(2)}-${RUN}`, userId, planId: plan.id, osTemplateId: os.id, nodeId, gamePlanId, status },
    });
  await server(gamer.id, sgp.id, gp.id);
  await server(vpsUser.id, fsn.id, null);
  await server(nobody.id, sgp.id, null, "DELETING"); // being deleted: counts for nothing
});

after(async () => { if (safe) await db.$disconnect(); });

const REGIONS = ["sgp1", "fsn1", "gra1"];
async function release(o: Record<string, unknown> = {}) {
  const r = await wn.saveRelease({ title: `R ${Math.random().toString(36).slice(2, 7)}`, highlights: [H()], ...o }, null, REGIONS);
  assert.ok(r.id, r.error);
  return r.id!;
}
const ids = async (u: U, now = NOW) => (await wn.listVisibleReleases(u, now)).map((r) => r.id);

test("drafts are invisible; publish makes them visible", { skip }, async () => {
  const id = await release();
  assert.equal((await ids(gamer)).includes(id), false);
  assert.deepEqual(await wn.publishRelease(id, null, new Date("2026-10-01T00:00:00Z")), {});
  assert.ok((await ids(gamer)).includes(id));
  await wn.unpublishRelease(id);
  assert.equal((await ids(gamer)).includes(id), false);
});

test("publish and schedule are refused while an item ships with the next update", { skip }, async () => {
  const id = await release({ highlights: [H(), H({ title: "Mods", availability: "NEXT_UPDATE" })] });
  assert.match((await wn.publishRelease(id, null)).error ?? "", /next update/);
  assert.match((await wn.scheduleRelease(id, new Date(NOW.getTime() + 3_600_000), null, NOW)).error ?? "", /next update/);
  await wn.markAllLive(id);
  assert.deepEqual(await wn.publishRelease(id, null, NOW), {});
});

test("scheduled releases appear only once their time passes", { skip }, async () => {
  const id = await release();
  const at = new Date(NOW.getTime() + 2 * 3_600_000);
  assert.match((await wn.scheduleRelease(id, new Date(NOW.getTime() - 1000), null, NOW)).error ?? "", /from now/);
  assert.deepEqual(await wn.scheduleRelease(id, at, null, NOW), {});
  assert.equal((await ids(gamer, NOW)).includes(id), false);
  assert.ok((await ids(gamer, new Date(at.getTime() + 1000))).includes(id));
});

test("audience + region targeting uses real servers and ignores ones being deleted", { skip }, async () => {
  const game = await release({ audience: "GAME" });
  const vps = await release({ audience: "VPS" });
  const sgp = await release({ regions: ["sgp1"] });
  for (const id of [game, vps, sgp]) await wn.publishRelease(id, null, NOW);
  const g = await ids(gamer), v = await ids(vpsUser), n = await ids(nobody);
  assert.ok(g.includes(game) && !g.includes(vps) && g.includes(sgp));
  assert.ok(!v.includes(game) && v.includes(vps) && !v.includes(sgp));
  assert.ok(!n.includes(game) && !n.includes(vps) && !n.includes(sgp), "a DELETING server targets nothing");
  const bad = await wn.saveRelease({ title: "x", highlights: [H()], regions: ["mars1"] }, null, REGIONS);
  const row = await db.updateAnnouncement.findUnique({ where: { id: bad.id! } });
  assert.deepEqual(row?.regions, [], "unknown regions are dropped");
});

test("read state: unread → snoozed → unread after a day → read; forged ids ignored", { skip }, async () => {
  const id = await release();
  const hidden = await release(); // stays a draft
  await wn.publishRelease(id, null, NOW);
  const state = async (now = NOW) => (await wn.listVisibleReleases(gamer, now)).find((r) => r.id === id)?.state;
  assert.equal(await state(), "UNREAD");
  assert.ok(await wn.snooze(gamer, id, NOW));
  assert.equal(await state(), "SNOOZED");
  assert.equal(await state(new Date(NOW.getTime() + 25 * 3_600_000)), "UNREAD");
  assert.equal(await wn.markRead(gamer, [id, hidden, "nope"], NOW), 1);
  assert.equal(await state(), "READ");
  assert.equal(await wn.snooze(gamer, id, NOW), false, "snooze never downgrades READ");
  assert.equal(await db.userAnnouncementSeen.count({ where: { announcementId: hidden } }), 0);
});

test("inbox: auto-opens the newest unread; pre-signup releases are not new", { skip }, async () => {
  const old = await release();
  await wn.publishRelease(old, null, new Date("2026-10-01T00:00:00Z"));
  const inbox = await wn.inboxFor(fresh, NOW);
  assert.equal(inbox.releases.find((r) => r.id === old)?.state, "READ");
  const newer = await release();
  await wn.publishRelease(newer, null, new Date(NOW.getTime() + 1000));
  const after = await wn.inboxFor(fresh, new Date(NOW.getTime() + 2000));
  assert.equal(after.autoOpenId, newer);
  assert.ok(after.unread >= 1);
});

test("customer payload never carries the owner-only availability flag", { skip }, async () => {
  const id = await release();
  await wn.publishRelease(id, null, NOW);
  const r = (await wn.listVisibleReleases(gamer, NOW)).find((x) => x.id === id)!;
  assert.equal("availability" in r.highlights[0], false);
});

test("email sweep: opt-in only, targeted verified customers, exactly once", { skip }, async () => {
  const quiet = await release({ audience: "GAME" });
  await wn.publishRelease(quiet, null, NOW);
  const loud = await release({ audience: "GAME", emailAnnounce: true });
  await wn.publishRelease(loud, null, NOW);
  const sent: string[] = [];
  const send = async (u: { id: string }, rel: { id: string }) => { sent.push(`${rel.id}:${u.id}`); return true; };
  const r1 = await wn.emailSweep(send, NOW, 100);
  const r2 = await wn.emailSweep(send, NOW, 100);
  assert.deepEqual(sent, [`${loud}:${gamer.id}`], "only the game owner, only the opted-in release, once");
  assert.ok(r1.done.includes(loud));
  assert.equal(r2.sent, 0);
  const row = await db.updateAnnouncement.findUnique({ where: { id: loud } });
  assert.ok(row?.emailStartedAt && row.emailFinishedAt);
  // Once sending started, saving cannot flip the toggle back on/off.
  await wn.saveRelease({ id: loud, title: row!.title, highlights: [H()], audience: "GAME", emailAnnounce: false }, null, REGIONS);
  assert.equal((await db.updateAnnouncement.findUnique({ where: { id: loud } }))?.emailAnnounce, true);
});

