// Screenshots for the What's New overhaul. Throwaway dev server + throwaway DB only.
//   node shots.mjs '<json ids>' [only]
import { chromium } from "playwright";
import { SignJWT } from "jose";
const BASE = process.env.BASE ?? "http://127.0.0.1:3488";
const OUT = "/root/agent-notes/whats-new";
const ids = JSON.parse(process.argv[2]);
const only = process.argv[3] || "all";
const want = (k) => only === "all" || only.split(",").includes(k);
const secret = new TextEncoder().encode(process.env.AUTH_SECRET);
const sess = (sub) => new SignJWT({ sub, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("1d").sign(secret);
const browser = await chromium.launch();
const DESK = { width: 1440, height: 900 }, PHONE = { width: 390, height: 844 };
async function ctx(user, viewport, { light = false, reduced = false } = {}) {
  const c = await browser.newContext({ viewport, deviceScaleFactor: viewport.width < 500 ? 2 : 1, reducedMotion: reduced ? "reduce" : "no-preference", isMobile: viewport.width < 500, hasTouch: viewport.width < 500 });
  await c.addCookies([{ name: "wn_session", value: await sess(user), url: BASE }, { name: "nx_cookie_consent", value: "accepted", url: BASE }]);
  await c.addInitScript((l) => { try { localStorage.setItem("nx-theme", l ? "light" : "dark"); localStorage.setItem("cookie-consent", "accepted"); } catch {} }, light);
  const p = await c.newPage();
  p.on("pageerror", (e) => console.log("PAGEERROR", e.message.slice(0, 200)));
  return { c, p };
}
async function hideNoise(p) {
  // Cookie banner + chat bubble are not part of this feature; hide them so the shots read.
  await p.addStyleTag({ content: `[aria-label="Cookie consent"],[data-cookie-consent],#cookie-consent{display:none!important}` }).catch(() => {});
  await p.evaluate(() => {
    for (const el of document.querySelectorAll("div,section,aside")) {
      const t = el.textContent || "";
      if (t.startsWith("We use cookies") && el.getBoundingClientRect().height < 260) el.style.display = "none";
    }
  });
}
async function shot(user, path, file, viewport, opts = {}) {
  const { c, p } = await ctx(user, viewport, opts);
  await p.goto(`${BASE}${path}`, { waitUntil: "load", timeout: 240000 });
  await p.waitForTimeout(opts.wait ?? 6000);
